package com.nkwabyte.cropdiseasedetection.common.data

/**
 * Ga (ga) body text, keyed by [DiseaseInfo.id].
 *
 * See [DiseaseTranslations] for the overlay contract. Ids absent from this map
 * fall back to English, so this file may be filled a few diseases at a time.
 *
 * The Twi vernacular name in `localName` is kept — it is the name a Ghanaian
 * farmer hears in the field — and only its gloss is translated.
 *
 * Product names, active ingredients, doses, concentrations and growth stages
 * are kept verbatim, as they appear on the label.
 *
 * Pending native-speaker review.
 */
object GaDiseaseText {
    val entries: Map<Int, DiseaseTranslation> = mapOf(

        // ── ABLE ──────────────────────────────────────────────────────────────

        0 to DiseaseTranslation(
            localName = "Aburo Nhwiren Tuntum (able baa lɛ he kpakpai hela)",
            description = "Atsɛɔ lɛ hu akɛ baa lɛ he kpakpa hela. Fɔŋ hela nɛɛ ji able hela ni fiteɔ nii babaoo yɛ je lɛ fɛɛ mli lɛ ekome. Edaraa yɛ latsa kɛ nyɔŋmɔ mli, ni kɛji eba yɛ ŋmɔ be lɛ shishijee lɛ, ebaanyɛ efite nii lɛ waa.",
            symptoms = "Kpakpai bibioo ni tamɔ ejwɛ, ni yɔɔ shɛɛ kɛyaashi ejurɔ, ni enyiɛɔ baa lɛ ntsɔi lɛ ahe. Kɛ be miiya nɔ lɛ, kpakpai lɛ lɛɛɔ ni efeɔ ejurɔ kwɔŋkwɔŋi ni ekpɛtɛɔ ni efiteɔ baa lɛ fã babaoo. Ŋmɔji ni hela lɛ eyɔɔ mli waa lɛ tamɔ nɔ ni la eshɛ nɔ.",
            causes = "Fɔŋ ni atsɛɔ lɛ Cercospora zeae-maydis, ni hiɔ able nii ni eshwɛ yɛ shikpɔŋ nɔ lɛ amli. Ekɛ ewui jieɔ kpo yɛ latsa kɛ nyɔŋmɔ be mli, ni kɔɔyɔɔ kɛ nugbɔnɛmɔ hoo kɛɔ yaa hei srɔtoi.",
            effects = "Ekpɔɔ baa ni feɔ niyenii lɛ nɔ, ni ehaa nii lɛ laajeɔ oha mli 10 kɛyaashi 50. Hela ni naa wa lɛ hãa tso lɛ enaa gbɔjɔɔ, no hewɔ lɛ egbeɔ shi dani abuɔ. Able lɛ hu esui jeɔ yɛ ŋmɔji ni hela lɛ eyɔɔ mli waa lɛ amli.",
            prevention = "Kɛ dumɔwu kpakpa ni damɔɔ hela lɛ naa tsu nii. Tsake nii ni odumɔɔ — kaadumɔ able yɛ able sɛɛ. Kɛ shikpɔŋ bu nii ni hela eyɔɔ mli lɛ nɔ. Ha he ahi tsei lɛ ateŋ koni kɔɔyɔɔ atsɔ mli. Kwɛmɔ ŋmɔ lɛ nɔ daa kɛjɛ ŋmɔ be lɛ teŋgbɛ.",
            organicMitigation = "• Kɛ Trichoderma tsofa (Trichoderma harzianum) wo shikpɔŋ mli ni ofɔɔ hu yɛ baa lɛ anɔ.\n• Fɔ neem mu (Azadirachta indica) yɛ otsi 3 kɛyaashi 4 fɛɛ mli.\n• Fɔ compost nu yɛ baa lɛ anɔ koni tso lɛ hewalɛ awa.\n• Jie baa ni hela eyɔɔ mli waa kɛ nii krokomɛi kɛjɛ jɛi ni ofite amɛ yɛ nikpamɔ sɛɛ.\n• Kɛ able kɛ agbamɔ dumɔ shi koni hela lɛ gbɛ akpata ni shikpɔŋ lɛ hu ahi.",
            chemicalMitigation = "• Azoxystrobin (Quadris): Kɛtsu nii kɛjɛ VT (fɔfɔi jeɔ kpo) kɛyaashi R1 (tsɔi jeɔ kpo) be mli. Fee ekoŋŋ yɛ gbii 14 sɛɛ kɛji ehe hiaa.\n• Pyraclostrobin + Boscalid (Pristine): Etsuɔ nii jogbaŋŋ; kɛtsu nii dani hela lɛ aaba.\n• Propiconazole (Tilt): Kɛtsu nii kɛji ona hela lɛ okadi klɛŋklɛŋ lɛ; nyiɛ susumɔnɔ ni yɔɔ wolo lɛ nɔ lɛ sɛɛ.\n• Trifloxystrobin: Obaanyɛ okɛfata propiconazole he yɛ tank lɛ mli koni etsu nii babaoo.\n• Tsakemɔ tsofai srɔtoi lɛ daa koni hela lɛ akadamɔ shi.",
        ),

        1 to DiseaseTranslation(
            localName = "Aburo Nhwiren Atoro (able baa lɛ he tsuru hela)",
            description = "Fɔŋ hela ni gbɛleɔ oya yɛ fɛi kɛ nyɔŋmɔ mli. Anaa kpɔkpɔi tsuru ni tamɔ tɛ tsuru yɛ baa lɛ afã enyɔ lɛ fɛɛ anɔ. Egbɛle yɛ Afrika Anaigbɛ, Ghana hu fata he, titri yɛ leebi ni fɛi kɛ bɔ yɔɔ mli.",
            symptoms = "Kpɔkpɔi ni tamɔ mfutuma, ni yɔɔ shɛɛ kɛyaashi tsuru tamɔ tɛ tsuru, yɛ baa lɛ hiɛ kɛ eshishi fɛɛ. Sɛɛ mli yɛ ŋmɔ be lɛ mli lɛ, kpɔkpɔi lɛ tsɔɔ diŋ. Baa ni hela lɛ eyɔɔ mli waa lɛ tsɔɔ sɛɛ ni egbo dani ebe eshɛ.",
            causes = "Fɔŋ ni atsɛɔ lɛ Puccinia sorghi. Kɔɔyɔɔ kɛ ewui jɛɔ wuoyigbɛ hei kɛbaa. Fɛi (16 kɛyaashi 23 °C) kɛ bɔ ni hiɔ baa lɛ nɔ etsɛɔ (ŋmɛlɛtswaai 6 kɛ nɔ ni fa fe nakai) yeɔ ebuaa hela lɛ.",
            effects = "Ekpɔɔ niyenii ni tso lɛ feɔ lɛ nɔ, ni ehaa nii laajeɔ oha mli 5 kɛyaashi 40, taakɛ be ni hela lɛ ba lɛ ji lɛ. Hela ni baa oya dani fɔfɔi aaje kpo lɛ fiteɔ nii fe fɛɛ. Tsei ni hela lɛ eyɔɔ mli waa lɛ awui tsiii ni amɛyiii obɔ.",
            prevention = "Dumɔ dumɔwui ni damɔɔ tsuru hela lɛ naa — enɛ ji gbɛ kpakpa fe fɛɛ kɛha be kakadaŋŋ. Dumɔ oya kpɔɔ be ni hela lɛ wui fa lɛ nɔ. Fite able ni ekwɛ ekɛ ehe kɛ tsei krokomɛi ni hiɛ hela lɛ. Kwɛmɔ ŋmɔ lɛ nɔ otsi fɛɛ otsi kɛjɛ V8 be lɛ nɔ.",
            organicMitigation = "• Dumɔ able srɔtoi ni damɔɔ hela lɛ naa yɛ adebɔɔ naa (bi dumɔwu hɔɔlɔi ni yɔɔ oshikpɔŋ nɔ).\n• Fite nii ni hela eyɔɔ mli kɛ able ni ekwɛ ekɛ ehe yɛ nikpamɔ sɛɛ.\n• Fɔ neem mu (oha mli 2 kɛyaashi 3) kɛji ona hela lɛ okadi klɛŋklɛŋ lɛ.\n• Sulfur mfutuma loo sulfur ni gbaa yɛ nu mli baanyɛ atsi hela ni baa oya lɛ naa.\n• Kwɛmɔ ni potassium ayɔɔ shikpɔŋ lɛ mli jogbaŋŋ — tsei ni bɛ lɛ naa hela oya.",
            chemicalMitigation = "• Mancozeb (Dithane M-45): Tsofa ni buɔ he; kɛtsu nii kɛji kpɔkpɔi klɛŋklɛŋ lɛ eje kpo.\n• Propiconazole (Tilt 250 EC): Eyaa tso lɛ mli; kɛtsu nii dani VT aaba koni etsu nii jogbaŋŋ.\n• Tebuconazole (Folicur): Etsuɔ nii jogbaŋŋ; kɛtsu nii kɛji hela lɛ eshɛ ŋmɔ lɛ oha mli 5.\n• Azoxystrobin: Ebuɔ he ni etsaa hela hu.\n• Kɛ tsofa lɛ tsu nii dani tsɔi aaje kpo kɛji tsuru hela lɛ yɛ jɛi — kɛji okɛtsu nii sɛɛ mli lɛ, sɛɛnamɔ bɛ he."
        ),

        2 to DiseaseTranslation(
            localName = "Aburo Pa (able ni yɔɔ hewalɛ mli)",
            description = "Able tso nɛɛ tsɔɔɔ hela, kooloo bibioo fitemɔ, loo niyenii hiamɔ okadi ko. Able ni yɔɔ hewalɛ mli lɛ baa yɔɔ akpawa ni kpɛɔ ni ewaa, ni eyaa nɔ koni eaawo nii kpakpa.",
            symptoms = "Baa akpawa ni yɔɔ pɛpɛɛpɛ ni kpɛɔ, kpakpai shɛɛ, kwɔŋkwɔŋi, sɛɛtsɔɔmɔ loo gbojemɔ bɛ he. Tsei ni ewaa ni edamɔ shi, fɔfɔi ni eje kpo jogbaŋŋ, kɛ able ni edara pɛpɛɛpɛ ni tsɔi ehã enɔ jogbaŋŋ.",
            causes = "Shikpɔŋ ni yɔɔ niyenii kpakpa, nugbɔnɛmɔ loo nushwiemɔ daa ni sa, dumɔwu kpakpa ni akwɛ, tsei ayibɔ ni sa, kɛ ŋmɔ mli nifeemɔi kpakpai fɛɛ.",
            effects = "Nii babaoo, able ni etsii, tsei ni ewaa ni egbeee shi. Tso lɛ baanyɛ ewo enii fɛɛ ni nɔ ni baafite yɛ nikpamɔ sɛɛ hu fioo.",
            prevention = "Ya nɔ nɔ ni ofeɔ lɛ nɔ. Nyiɛ ŋmɔ lɛ mli daa (otsi fɛɛ otsi shikome kwraa) koni onaa hela loo kooloo bibioo okadi klɛŋklɛŋ dani ewaa. Ŋmalɛ nii ni okɛtsuɔ nii fɛɛ koni ebua bo wɔsɛɛ.",
            organicMitigation = "• Ya nɔ nɔ okɛ compost loo adebɔɔ nii wooɔ shikpɔŋ mli koni shikpɔŋ lɛ wala ahi shi.\n• Tsake nii ni odumɔɔ ni okɛ agbamɔ (agbamɔ, soya) atsu nii koni nitrogen aya nɔ yɛ adebɔɔ gbɛ nɔ.\n• Kɛ nii srɔtoi dumɔ shi koni oná ŋmɔ lɛ he sɛɛnamɔ ni jwɛi akashwie.\n• Ya nɔ ofɔɔ niyenii bibioi yɛ baa lɛ anɔ kɛji ofeɔ nakai lɛ.\n• Ma nu he ni okɛbaato (kpɔi, jwɛi ni agbi ni akɛtsɔɔ shikpɔŋ nɔ) koni nu ahi shikpɔŋ mli.",
            chemicalMitigation = "• Kɛ NPK ŋmɔ mli tsofa ni sa (okadi 15-15-15 loo 23-10-5) tsu nii yɛ susumɔnɔ ni awie he lɛ nɔ.\n• Kɛ urea (46-0-0) wo tso lɛ masɛi yɛ nakutso be (V6) mli koni nitrogen aya nɔ.\n• Je fɔŋ tsofa ni buɔ he shishi yɛ fɔfɔi be mli kɛji ŋmɔ be ni eho lɛ mli hela yɛ jɛi.\n• Kaakɛ kooloo bibioi atsofa tsu nii kɛha tso lɛ mli kooloi akɛji fitemɔ lɛ eshɛ oha mli 10.\n• Nyiɛ CABI loo MoFA (Ghana Niyenii kɛ Ŋmɔ Nitsumɔ Ŋɔɔ) fɔmɔ gbɛjianɔtoo lɛ sɛɛ."
        ),

        3 to DiseaseTranslation(
            localName = "Aburo Nhwiren Ohow (able baa shãa hela)",
            description = "Fɔŋ hela ni fiteɔ nii. Ekpɔɔ baa lɛ nɔ oya ni ekpɔɔ niyenii ni tso lɛ feɔ lɛ nɔ waa. Kpakpai wuji ni tamɔ sigareti, ni yɔɔ shɛɛ, ji eokadi krɛdɛɛ. Enaa waa yɛ hei ni latsa fa jaaa ni bɔ hiɔ shi etsɛɔ, tamɔ Ghana kooi ahei lɛ.",
            symptoms = "Kpakpai wuji kakadaŋŋ ni tamɔ sigareti (sɛntimita 3 kɛyaashi 15), ni yɔɔ ejurɔ-akpawa kɛyaashi shɛɛ, ni enyiɛɔ baa lɛ ntsɔi lɛ ahe. Amɛjeɔ shishi kɛjɛ baa ni yɔɔ shishi lɛ anɔ ni amɛkwɔɔ. Baa fã ni hela lɛ eyɔɔ mli lɛ tsɔɔ shɛɛ loo ejurɔ, ni ebaanyɛ etsɔ diŋ be ni fɔŋ lɛ jieɔ ewui kpo lɛ.",
            causes = "Fɔŋ Exserohilum turcicum (tsutsu lɛ atsɛɔ lɛ Helminthosporium turcicum). Ehiɔ able nii ni eshwɛ lɛ amli. Latsa ni faaa tsɔ (18 kɛyaashi 27 °C) kɛ bɔ ni hiɔ baa lɛ nɔ etsɛɔ (ŋmɛlɛtswaai 6 kɛ nɔ ni fa) yeɔ ebuaa lɛ. Kɔɔyɔɔ kɛ nugbɔnɛmɔ hoo kɛɔ ewui yaa.",
            effects = "Ebaanyɛ eha nii laaje oha mli 30 kɛyaashi 50 kɛji eba dani loo be ni fɔfɔi jeɔ kpo. Baa ni gbeɔ shi babaoo kpɔɔ able lɛ yimɔ kɛ etsii nɔ. Hela ni naa wa ni baa oya baanyɛ eha nii lɛ afite kwraa yɛ dumɔwui ni damɔɔ enaa nɔ.",
            prevention = "Dumɔ dumɔwui ni damɔɔ hela lɛ naa — enɛ ji nɔ ni he hiaa fe fɛɛ. Tsake nii ni odumɔɔ ni okɛ tsei ni jeee jwɛi (agbamɔ, abolo) atsu nii. Kɛ shikpɔŋ bu nii ni hela eyɔɔ mli lɛ nɔ yɛ nikpamɔ sɛɛ koni hela wui lɛ akpɔtɔ. Kaakɛ nitrogen babaoo tsu nii, ejaakɛ ehaa tso lɛ feɔ mlɛo ni enaa hela oya.",
            organicMitigation = "• Kɛ able srɔtoi ni damɔɔ hela lɛ naa tsu nii (taomɔ srɔtoi ni CSIR-SARI loo IITA ejie kpo yɛ Ghana).\n• Kɛ Trichoderma harzianum wo shikpɔŋ mli ni ofɔɔ hu yɛ baa lɛ anɔ.\n• Neem yibii ni akwɛ ni akɛwo shikpɔŋ mli kpɔɔ hela wui ni yɔɔ shikpɔŋ mli lɛ nɔ.\n• Jie tsei afãi ni hela eyɔɔ mli lɛ kɛjɛ jɛi ni ofite amɛ yɛ nikpamɔ sɛɛ — kaashi nii yɛ ŋmɔ lɛ mli.\n• Kɛ agbamɔ kɛ able dumɔ shi koni hela lɛ gbɛ akpata.",
            chemicalMitigation = "• Propiconazole (Tilt 250 EC): Kɛtsu nii yɛ V8–V10 be mli dani fɔfɔi aaje kpo; fee ekoŋŋ gbii 14 fɛɛ mli.\n• Azoxystrobin: Etsuɔ nii jogbaŋŋ akɛ hebumɔ; kɛtsu nii kɛji ona hela lɛ okadi klɛŋklɛŋ lɛ.\n• Pyraclostrobin + Metconazole (Headline AMP): Etsaa helai babaoo; ehi waa kɛha hela nɛɛ.\n• Mancozeb: Tsofa ni buɔ he; kɛtsu nii dani hela lɛ aaba be ni ŋwɛi shishɔŋ sa lɛ mli.\n• Tsofa ni akɛtsuɔ nii dani tsɔi aaje kpo lɛ ji sɛɛnamɔ ni fe fɛɛ."
        ),

        4 to DiseaseTranslation(
            localName = "Aburo Nhwiren Mfirimiri (able baa kwɔŋkwɔŋi hela)",
            description = "Able baa kwɔŋkwɔŋi hela ji able hela ni fiteɔ nii fe fɛɛ yɛ Afrika. Maize Streak Virus (MSV) kɛbaa, ni kooloo bibioo ni atsɛɔ lɛ leafhopper kɛɔ yaa. Eyɔɔ Afrika ni yɔɔ Sahara wuoyigbɛ lɛ fɛɛ mli, Ghana hu fata he. Dumɔwui ni damɔɔɔ enaa lɛ baanyɛ elaaje nii lɛ fɛɛ kɛkɛ.",
            symptoms = "Kwɔŋkwɔŋi bibioi ni kpɔtɔɔ, ni yɔɔ yɛŋ-sɛɛ, jeɔ kpo yɛ baa lɛ ntsɔi ahe, ni efeɔ subaŋ ni yɔɔ akpawa kɛ sɛɛ. Tsei ni hela lɛ eyɔɔ mli waa lɛ daraaa ni amɛ able hu bibioi loo ehiii. Yɛ naagbee lɛ, baa lɛ baanyɛ etsɔ yɛŋ ni etsɔ sɛɛ kwraa.",
            causes = "Maize Streak Virus (MSV), Geminivirus ni kooloo bibioo leafhopper (Cicadulina spp.) kɛɔ yaa. Hela wu lɛ nyɛɛɛ egbɛle kɛtsɔ shikpɔŋ loo hetamɔ nɔ — ehe hiaa kooloo bibioo lɛ. Leafhopper faa yɛ latsa kɛ gbiŋ be mli.",
            effects = "Nii laajemɔ ni ji oha mli 30 kɛyaashi 100, taakɛ dumɔwu lɛ kɛ tso lɛ afii ni ji be ni hela lɛ ba lɛ. Hela ni baa oya (yɛ otsii enyɔ mli yɛ shwiemɔ sɛɛ) hãa nii lɛ fɛɛ fiteɔ. Tsei ni daraaa lɛ woɔɔ able ko ni sɛɛnamɔ yɔɔ he. Enɛ ji naagba wulu kɛha ŋmɔlɔi bibioi yɛ Ghana.",
            prevention = "Gbɛ kpakpa fe fɛɛ ji ni oaadumɔ dumɔwui ni damɔɔ MSV naa — nɔ ni yɔɔ damɔmɔ dumɔwu bɔɔ nii lɛ (okadi STRIGA 6, STRIGA 4, loo dumɔwui ni IITA ejie kpo). Dumɔ oya kpɔɔ be ni leafhopper fa lɛ nɔ. Jie jwɛi kɛjɛ ŋmɔ lɛ masɛi, ejaakɛ jɛi ji leafhopper ahiɛshi.",
            organicMitigation = "• Dumɔ dumɔwui ni akwɛ akɛ edamɔɔ MSV naa (awieɔ enɛ he waa).\n• Dumɔ oya (nugbɔnɛmɔ shishijee): tsei lɛ aaadara dani leafhopper aaafa.\n• Kɛ able kɛ agbamɔ loo duade dumɔ shi koni leafhopper nyiɛmɔ atsi.\n• Jie tsei ni hela lɛ eyɔɔ mli waa lɛ oya koni hela wui lɛ ahiɛshi akpɔtɔ.\n• Ha ŋmɔ lɛ masɛi akahi jwɛi, ejaakɛ jɛi leafhopper hiɔ.\n• Sɛɛ ni yɔɔ sɛɛ ni mɔɔ nii buaa koni oná leafhopper ayibɔ ale.",
            chemicalMitigation = "• Imidacloprid dumɔwu tsofa (Gaucho 600 FS): Etsuɔ nii jogbaŋŋ ni ebuɔ tsei bibioi ahe kɛjɛ leafhopper kãmɔ he yɛ otsii 3 klɛŋklɛŋ ni he hiaa lɛ amli.\n• Thiamethoxam dumɔwu tsofa (Cruiser): Imidacloprid najiaŋtsɔɔlɔ kɛha hebumɔ ni baa oya.\n• Kooloo bibioi atsofa ni afɔɔ (Dimethoate, Chlorpyrifos): Kɛtsu nii kɛha leafhopper kɛji akɛ tsofa ko ekãaa dumɔwu lɛ he; kɛtsu nii kɛji ona leafhopper klɛŋklɛŋ lɛ.\n• Kadimɔ: Kooloo bibioi atsofa gbeɔ kooloo lɛ shi etsaaa tso ni hela eyɔɔ mli lɛ. Ha ojwɛŋmɔ ahi hebumɔ nɔ."
        ),

        // ── FAMAI ─────────────────────────────────────────────────────────────

        5 to DiseaseTranslation(
            localName = "Mako Nhwiren Ponko (fama baa kpakpai hela)",
            description = "Kooloo bibioo hela ni fiteɔ nii. Eyɔɔ fama baa, tso kɛ eyibii ahe yɛ latsa kɛ nyɔŋmɔ mli. Egbɛle yɛ Ghana ŋmɔ hei ni bɔ yɔɔ lɛ amli. Baa ni gbeɔ shi oya kɛ kpakpai ni yɔɔ yibii anɔ hãa shika laajeɔ waa, titri kɛha fama ni akɛyaa maŋsɛɛ.",
            symptoms = "Kpakpai bibioi ni tamɔ kokloi, ni yɔɔ diŋ ni tamɔ nɔ ni nu eyɔɔ mli, yɛ baa lɛ anɔ (milimita 2 kɛyaashi 10), ni etsɔɔ shɛɛ ni sɛɛ ebɔle he. Kpakpai lɛ baanyɛ akpɛtɛ ni afee hei wuji ni egbo. Baa ni tsɔɔ sɛɛ ni egbeɔ shi lɛ hãa hulu shɛɔ yibii lɛ anɔ. Yibii lɛ náa kpakpai diŋ ni tsɔɔ ŋwɛi tamɔ he kpakpa, ni ekpɔɔ ajara yɛ jara nɔ.",
            causes = "Kooloo bibioo Xanthomonas campestris pv. vesicatoria (kɛ X. perforans kɛ X. euvesicatoria hu). Egbɛleɔ kɛtsɔ nugbɔnɛmɔ hoo, nushwiemɔ ni jɛɔ ŋwɛi, nitsumɔ nii ni hela eyɔɔ he, dumɔwui ni hela eyɔɔ mli, kɛ tsei ni adumɔ nɔ. Latsa (25 kɛyaashi 30 °C) kɛ bɔ ni yɔɔ baa lɛ nɔ buaa lɛ.",
            effects = "Baa ni gbeɔ shi waa hãa tso lɛ enaa gbɔjɔɔ ni ehãa hulu kɛ helai krokomɛi shɛɔ yibii ni miidara lɛ anɔ. Kpakpai ni yɔɔ yibii anɔ kpɔɔ ajara oha mli 40 kɛyaashi 60. Nii laajemɔ baanyɛ eshɛ oha mli 50 yɛ nugbɔ be mli. Akpooɔ fama ni akɛyaa maŋsɛɛ yɛ kpakpai lɛ hewɔ.",
            prevention = "Kɛ dumɔwui kɛ tsei ni akwɛ akɛ hela bɛ amɛhe pɛ tsu nii, kɛjɛ hɔɔlɔi ni ayeɔ amɛnɔ dɛŋ. Kaashwie nu kɛjɛ ŋwɛi — kɛ nushwiemɔ ni nyiɛɔ shikome shikome loo ni nyiɛɔ gbɛi anɔ tsu nii. Kpɔɔ nyiɛmɔ yɛ ŋmɔ ni bɔ yɔɔ mli nɔ. Fɔ nitsumɔ nii ahe yɛ tso fɛɛ tso sɛɛ. Tsake nii ni odumɔɔ afii 2 kɛyaashi 3 ni okɛ nii ni jeee fama weku atsu nii.",
            organicMitigation = "• Kɛ kɔpa tsofa ni akpɛlɛ nɔ kɛha adebɔɔ ŋmɔ nitsumɔ (Bordeaux mixture: kɔpa sulfate oha mli 1 + tɛ ŋɔɔ) tsu nii akɛ hebumɔ gbii 7 kɛyaashi 10 fɛɛ mli.\n• Kɛ neem mu (oha mli 2) kɛ castile shɔ (oha mli 0.5) fɔ koni kooloo bibioi lɛ akpɔtɔ ni tso lɛ hewalɛ awa.\n• Jie baa ni hela eyɔɔ mli kɛ tsei anii kɛjɛ jɛi ni ofite amɛ.\n• Kɛ nii tsɔɔ tso lɛ shishi koni shikpɔŋ hoo akashɛ baa ni yɔɔ shishi lɛ anɔ.\n• Compost ni akɛwoɔ shikpɔŋ mli hãa shikpɔŋ lɛ wala hiɔ ni tso lɛ náa hewalɛ.",
            chemicalMitigation = "• Copper hydroxide (Kocide 3000): Enɛ akɛtsuɔ nii fe fɛɛ; kɛtsu nii gbii 7 fɛɛ mli yɛ bɔ be mli.\n• Copper oxychloride + Mancozeb (Cuprosan): Fatamɔ ni tsuɔ nii kɛha kooloo bibioi kɛ fɔŋ hela.\n• Streptomycin sulfate (he ni mla ŋmɛɔ gbɛ): Kɛtsu nii yɛ hela lɛ shishijee, ni otsake lɛ kɛ kɔpa teŋ.\n• Acibenzolar-S-methyl (Actigard): Ehãa tso lɛ diɛŋtsɛ ehewalɛ teɔ shi — kɛtsu nii kɛfata kɔpa he.\n• Kaakɛ kɔpa tsu nii yɛ latsa kɛ hulu ni naa wa mli koni ekafite tso lɛ."
        ),

        6 to DiseaseTranslation(
            localName = "Mako Nhwiren Akyekyere (fama baa pɔŋ hiŋmɛi hela)",
            description = "Atsɛɔ lɛ hu akɛ pɔŋ hiŋmɛi kpakpa hela. Fɔŋ hela nɛɛ kɛ kpakpai ni tamɔ kokloi ni amɛteŋ yɔɔ yɛŋ ni amɛnaa yɔɔ diŋ lɛ baa, tamɔ pɔŋ hiŋmɛi. Efa yɛ Ghana yɛ bɔ kɛ nugbɔ be mli. Hela ni baa shii abɔ yɛ ŋmɔ be lɛ mli hãa baa gbeɔ shi fiofio.",
            symptoms = "Kpakpai ni tamɔ kokloi (milimita 5 kɛyaashi 15) ni amɛteŋ yɔɔ shɛɛ kɛyaashi ejurɔ ni amɛnaa yɔɔ shɛɛ diŋ kɛyaashi bluu. Ateŋ lɛ baanyɛ ejɛ mli ni eshi gbolɔ. Baa tsɔɔ sɛɛ ebɔle kpakpai lɛ ahe ni naagbee lɛ egbeɔ shi. Hela ni fa hãa baa fɛɛ gbeɔ shi.",
            causes = "Fɔŋ Cercospora capsici. Ehiɔ tsei anii ni hela eyɔɔ mli lɛ amli. Ajieɔ ewui kpo ni egbɛleɔ yɛ latsa (25 kɛyaashi 30 °C), bɔ kɛ nugbɔ mli. Akɛtsɔɔ dumɔwui ni hela eyɔɔ mli hu nɔ gbɛleɔ.",
            effects = "Baa ni gbeɔ shi fiofio kpɔɔ niyenii ni tso lɛ feɔ lɛ nɔ ni ehãa hulu shɛɔ yibii lɛ anɔ. Nii laajemɔ ni ji oha mli 20 kɛyaashi 40 fa yɛ ŋmɔji ni akwɛɛɛ nɔ lɛ amli. Baa ni gbeɔ shi shii abɔ hãa tso lɛ enaa gbɔjɔɔ ni enaa helai krokomɛi oya.",
            prevention = "Dumɔ kɛjɛ dumɔwui ni akwɛ akɛ amɛhe tse mli. Ha he ahi (sɛntimita 60 yɛ tsei ateŋ) koni kɔɔyɔɔ atsɔ mli. Jie tsei anii ni hela eyɔɔ mli lɛ oya. Tsake nii ni odumɔɔ afii 2 kwraa ni okɛ nii ni jeee fama weku atsu nii.",
            organicMitigation = "• Fɔ kɔpa sulfate (Bordeaux mixture) akɛ hebumɔ gbii 10 kɛyaashi 14 fɛɛ mli.\n• Fɔ neem mu kɛ bicarbonate fatamɔ (baking soda kpaŋmɔ bibioo 1 + neem mu kpaŋmɔ wulu 1 yɛ lita fɛɛ lita mli).\n• Jie baa kɛ nii fɛɛ ni hela eyɔɔ mli lɛ kɛjɛ jɛi ni ofite amɛ.\n• Kɛ Trichoderma harzianum wo shikpɔŋ mli akɛ nu koni hela wui ni yɔɔ shikpɔŋ mli lɛ akpɔtɔ.\n• He ni hi kɛ tsei afolɔmɔ hãa kɔɔyɔɔ tsɔɔ mli ni bɔ ni yɔɔ tso lɛ he lɛ kpɔɔ.",
            chemicalMitigation = "• Mancozeb (Dithane M-45): Ebuɔ he; kɛtsu nii gbii 7 kɛyaashi 10 fɛɛ mli yɛ bɔ be mli.\n• Chlorothalonil (Bravo 500): Ebuɔ he jogbaŋŋ; kɛtsu nii gbii 7 kɛyaashi 14 fɛɛ mli.\n• Azoxystrobin (Amistar): Eyaa tso lɛ mli; kɛtsu nii kɛji ona hela lɛ okadi klɛŋklɛŋ lɛ.\n• Difenoconazole (Score 250 EC): Eyaa tso lɛ mli; kɛtsu nii gbii 14 fɛɛ mli koni etsa hela lɛ.\n• Tsake tsofai awekui lɛ yɛ shii 2 kɛyaashi 3 fɛɛ sɛɛ koni hela lɛ akadamɔ shi."
        ),

        7 to DiseaseTranslation(
            localName = "Mako Nhwiren Ohow (fama baa shãa hela)",
            description = "Fɔŋ hela ni yɔɔ baa momoi ni yɔɔ shishi lɛ ahe klɛŋklɛŋ, ni efeɔ kpakpai ni bɔlei ebɔle he tamɔ nɔ ni akɛ tu shwieɔ nɔ. Efa yɛ Ghana fama hei fɛɛ, titri yɛ nugbɔ be mli be ni latsa kɛ bɔ hiɔ shi.",
            symptoms = "Kpakpai shɛɛ kɛyaashi diŋ (milimita 10 kɛyaashi 15) ni bɔlei ebɔle he ni ehãa etamɔ nɔ ni akɛ tu shwieɔ nɔ, klɛŋklɛŋ yɛ baa momoi ni yɔɔ shishi lɛ anɔ. Sɛɛ baanyɛ ebɔle kpakpai lɛ ahe. Kpakpai lɛ hãa baa tsɔɔ sɛɛ ni egbeɔ shi. Kɛji enaa wa lɛ, baa gbeɔ shi kɛyaa ŋwɛi oya.",
            causes = "Fɔŋ Alternaria capsici loo A. alternata. Amɛyɔɔ shikpɔŋ mli kɛ dumɔwu mli fɛɛ. Amɛhiɔ nii ni hela eyɔɔ mli lɛ amli. Latsa (24 kɛyaashi 29 °C), bɔ ni fa, kɛ nu kɛ gbiŋ ni tsakeɔ buaa amɛ.",
            effects = "Baa gbeɔ shi kɛjɛ tso lɛ shishi kɛyaa ŋwɛi, ni ekpɔɔ niyenii ni tso lɛ feɔ lɛ nɔ waa. Yibii ni yɔɔ jɛi lɛ shãa yɛ hulu mli ni amɛfiteɔ. Kɛji akɛ tsofa ko etsuuu nii lɛ, nii laajemɔ baanyɛ eshɛ oha mli 30 kɛyaashi 50 yɛ ŋmɔ ni hela eyɔɔ mli waa lɛ mli.",
            prevention = "Shwie nu tso lɛ shishi pɛ — kaaha nu ashɛ baa lɛ anɔ. Tsake nii ni odumɔɔ afii 2 kwraa ni okɛ tsei ni jeee fama weku atsu nii. Kɛ tso damɔ tsei lɛ ahe koni baa akatã shikpɔŋ. Jie baa ni yɔɔ shishi ni tãa shikpɔŋ lɛ. Kaakɛ nitrogen babaoo tsu nii, ejaakɛ ehãa tso lɛ feɔ mlɛo ni enaa hela.",
            organicMitigation = "• Kɛ compost tsɔɔ tso lɛ shishi (kɛkɛ sɛntimita 5) koni shikpɔŋ hoo akashɛ baa lɛ anɔ.\n• Fɔ kɔpa sulfate (Bordeaux mixture) akɛ hebumɔ.\n• Fɔ neem mu (oha mli 2 kɛyaashi 3) koni fɔŋ lɛ akadara.\n• Bicarbonate kɛ neem mu ni afɔɔ yɛ baa lɛ anɔ tsakeɔ baa lɛ hiɛ shishɔŋ ni etsiɔ fɔŋ lɛ naa.\n• Jie baa ni yɔɔ shishi ni hela eyɔɔ mli lɛ kɛjɛ jɛi kɛji ona amɛ pɛ.",
            chemicalMitigation = "• Chlorothalonil (Bravo 500): Kɛtsu nii gbii 7 kɛyaashi 10 fɛɛ mli akɛ hebumɔ yɛ bɔ be mli.\n• Iprodione (Rovral): Tsofa ni tsaa Alternaria; kɛtsu nii yɛ hela lɛ shishijee.\n• Azoxystrobin (Amistar): Eyaa tso lɛ mli; kɛtsu nii akɛ hebumɔ yɛ dumɔ be mli ni gbii 14 fɛɛ mli.\n• Boscalid + Pyraclostrobin (Bellis): Fatamɔ kpakpa ni tsuɔ nii kɛha Alternaria.\n• Copper oxychloride: Kɛtsu nii akɛ hebumɔ gbii 10 fɛɛ mli yɛ nugbɔ be mli."
        ),

        8 to DiseaseTranslation(
            localName = "Mako Kobuo (fama gbojemɔ hela)",
            description = "Fɔŋ hela ni yɔɔ shikpɔŋ mli ni fiteɔ nii waa. Eyaa fama tso lɛ nu gbɛi amli, ni ehãa tso lɛ gbojeɔ fiofio kɛyashi egboɔ. Kɛji ebote ŋmɔ ko mli lɛ, ehiɔ shikpɔŋ lɛ mli afii babaoo. Efa yɛ Ghana fama ni akɛ nu shwieɔ nɔ lɛ amli.",
            symptoms = "Baa ni yɔɔ shishi lɛ tsɔɔ sɛɛ ni ekwɔɔ. Tso lɛ niji gbojeɔ yɛ shwane latsa mli, ni kɛji ashwie nu nɔ po lɛ ehiii. Tsei lɛ gbeɔ shi ni amɛgboɔ naagbee lɛ. Tso lɛ mli su tsakeɔ — anaa kwɔŋkwɔŋi shɛɛ kɛyaashi tsuru kɛji afolɔ tso lɛ yɛ eshishi.",
            causes = "Fɔŋ Fusarium oxysporum f.sp. capsici ni yɔɔ shikpɔŋ mli. Ebotea shishifai amli kɛtsɔ pilamɔ loo adebɔɔ gbɛi anɔ. Ehiɔ shikpɔŋ mli afii 20 kɛ nɔ ni fa akɛ chlamydospores. Shikpɔŋ ni latsa yɔɔ mli (25 kɛyaashi 30 °C), nu ni fa yɛ gbiŋ sɛɛ, kɛ shikpɔŋ ni kaa buaa lɛ.",
            effects = "Tso lɛ gboɔ yɛ gbii loo otsii fioo sɛɛ. Nii lɛ fɛɛ baanyɛ afite kɛji ŋmɔ lɛ fɛɛ ená hela lɛ. Shikpɔŋ lɛ yaa nɔ ehiɛ hela lɛ afii babaoo — fama ni aaadumɔ jɛi wɔsɛɛ lɛ baaná nɔŋŋ. Tsamɔ ko bɛ he kɛji tso lɛ ená hela lɛ.",
            prevention = "Kaadumɔ fama ekoŋŋ yɛ ŋmɔ ni hela nɛɛ eba mli pɛŋ lɛ mli kɛyashi afii 5. Ha shikpɔŋ lɛ pH aya 6.5 nɔ kɛtsɔ tɛ ŋɔɔ ni okɛwoɔ mli nɔ. Ha nu ajɛ shikpɔŋ lɛ mli jogbaŋŋ — kaaha nu adamɔ shi. Fɔ nii ni okɛdumɔɔ lɛ ahe. Ná tsei bibioi kɛjɛ dumɔhei ni akwɛ pɛ.",
            organicMitigation = "• Shikpɔŋ shãa kɛ hulu: Kɛ plastik ni hiɛ tse tsɔɔ shikpɔŋ ni bɔ yɔɔ mli lɛ nɔ otsii 4 kɛyaashi 6 yɛ latsa be mli koni hela wui ni yɔɔ shikpɔŋ mli lɛ akpɔtɔ waa.\n• Kɛ Trichoderma harzianum wo shikpɔŋ mli (akɛ nu loo okɛfata dumɔ gbolɔ lɛ he): ehiɔ shishifai ahe ni etsiɔ Fusarium naa.\n• Kɛ fɔŋi kpakpai (Glomus spp.) wo shishifai ahe yɛ dumɔ be mli koni shishifai lɛ hewalɛ awa.\n• Kɛ neem yibii ni akwɛ wo shikpɔŋ mli — egbeɔ Fusarium.\n• Kɛ dumɔwui ni damɔɔ hela lɛ naa tsu nii he ni amɛyɔɔ.",
            chemicalMitigation = "• Metalaxyl (Ridomil): Shwie shikpɔŋ mli yɛ dumɔ be mli akɛ hebumɔ; etsaaa tso ni hela eyɔɔ mli lɛ.\n• Carbendazim (Bavistin): Shwie shikpɔŋ mli loo kɛfee dumɔwu tsofa; kɛtsu nii akɛ hebumɔ pɛ.\n• Thiram dumɔwu tsofa: Ebuɔ tsei bibioi ashishifai ahe yɛ daramɔ be mli.\n• Fludioxonil: Dumɔwu tsofa ni tsuɔ nii kɛha Fusarium shishi fitemɔ.\n• Nɔ ni he hiaa: Tsofa ko tsaaa hela lɛ kɛji ebote mli momo — hebumɔ ji nɔ titri."
        ),

        9 to DiseaseTranslation(
            localName = "Mako Pa (fama ni yɔɔ hewalɛ mli)",
            description = "Fama tso nɛɛ yɔɔ hewalɛ mli jogbaŋŋ: baa akpawa ni yɔɔ diŋ, tsei ni ewaa, kɛ yibii ni miidara jogbaŋŋ. Fama ni yɔɔ hewalɛ mli tsɔɔ akɛ anyiɛɔ ŋmɔ nitsumɔ gbɛi kpakpai anɔ ni nii lɛ yaa nɔ jogbaŋŋ.",
            symptoms = "Baa akpawa ni yɔɔ diŋ ni kpɛɔ, amɛnaa yɔɔ tromtrom, kpakpai loo sɛɛtsɔɔmɔ bɛ he. Tsei ni ewaa ni edamɔ shi. Fɔfɔi babaoo, yɛŋ loo bluu. Fama ni ewaa ni ekpɛɔ, edara ni sa ni fitemɔ ko bɛ he.",
            causes = "Shikpɔŋ kpakpa (pH 6.0 kɛyaashi 6.8), bɔ ni akwɛɔ nɔ daa, he ni sa yɛ tsei ateŋ, niyenii ni sa (NPK kɛ niyenii bibioi), kɛ kooloo bibioi kɛ jwɛi ni akwɛɔ amɛnɔ jogbaŋŋ.",
            effects = "Yibii babaoo ni sa jara nɔ. Tsei ni ewaa lɛ damɔɔ gbiŋ kɛ helai anaa. Nii ni woɔ daa buaa ŋmɔlɔ shika kɛ shia niyenii.",
            prevention = "Ha shikpɔŋ lɛ mli bɔ ahi shi daa kɛtsɔ nushwiemɔ ni nyiɛɔ shikome shikome loo nushwiemɔ ni afeɔ daa nɔ. Kɛ nii tsɔɔ shikpɔŋ nɔ koni bɔ ahi mli ni jwɛi akashwie. Kwɛmɔ daa koni ona kooloo bibioi kɛ helai okadi klɛŋklɛŋ. Ŋmalɛ ŋmɔ lɛ he saji koni onyiɛ nɔ ni okɛtsuɔ nii kɛ nɔ ni ona lɛ sɛɛ.",
            organicMitigation = "• Kɛ compost ni efite jogbaŋŋ (kilo 2 kɛyaashi 3 kɛha tso fɛɛ tso) wo mli yɛ dumɔ be mli kɛ sɛɛ mli.\n• Kɛ jwɛi loo jwɛi ni egbi (sɛntimita 8 kɛyaashi 10) tsɔɔ shikpɔŋ nɔ koni bɔ ahi mli ni jwɛi akashwie.\n• Dumɔ basil loo marigold fama lɛ he koni ekɛ kooloo bibioi kɛ kooloo yɛŋi ashi yɛ adebɔɔ gbɛ nɔ.\n• Fɔ neem mu akɛ hebumɔ otsii 2 kɛyaashi 3 fɛɛ mli koni ekɛ kooloo bibioi ashi ni fɔŋ helai bibioi akpɔtɔ.\n• Fɔ loofɔlɔ nu loo tsei anu ni ekaa yɛ baa lɛ anɔ koni tso lɛ hewalɛ awa.",
            chemicalMitigation = "• Kɛ NPK ŋmɔ mli tsofa ni sa tsu nii (okadi 12-12-17 yɛ yibii be mli).\n• Kɛ calcium nitrate fata he koni yibii lɛ shishi akafite.\n• Kɛ magnesium sulfate (Epsom salt ni afɔɔ yɛ baa lɛ anɔ) tsu nii kɛji ona sɛɛtsɔɔmɔ yɛ ntsɔi ateŋ.\n• Fɔ kɔpa akɛ hebumɔ yɛ nugbɔ be shishijee.\n• Kɛ kooloo bibioi atsofa kã dumɔwu lɛ he yɛ dumɔhe be mli koni ebu tsei bibioi ahe."
        ),

        10 to DiseaseTranslation(
            localName = "Mako Nhwiren Kwanee (fama baa gbomɔ hela)",
            description = "Hela ni fiteɔ nii waa ni Phytophthora infestans kɛbaa (hela ni kɛ Ireland hɔmɔ wulu lɛ ba lɛ nɔŋŋ). Ebaanyɛ efite fama ŋmɔji fɛɛ yɛ gbii fioo mli yɛ fɛi kɛ nyɔŋmɔ mli. Egbɛleɔ oya waa hewɔ lɛ eji helai ni asheɔ agbeyei yɛ je lɛ fɛɛ mli lɛ ekome.",
            symptoms = "Kpakpai ni yɔɔ diŋ ni tamɔ nɔ ni akɛ mu efɔ nɔ ni tamɔ nɔ ni nu eyɔɔ mli, yɛ baa kɛ tsei ahe, ni egbɛleɔ oya. Fɔŋ yɛŋ ni tamɔ ntɔ yɛ baa lɛ eshishi yɛ bɔ mli. Tsei náa kpakpai shɛɛ diŋ ni amɛbaanyɛ agbe shi. Yibii náa kpakpai shɛɛ diŋ ni ewaa.",
            causes = "Phytophthora infestans (jeee fɔŋ diɛŋtsɛ). Egbɛleɔ kɛtsɔ kɔɔyɔɔ nɔ yɛ fɛi (15 kɛyaashi 20 °C) kɛ bɔ mli. Ebaanyɛ eya kilomita babaoo yɛ kɔɔyɔɔ mli. Edaraa yɛ nyɔŋ ni fɛi yɔɔ mli kɛ leebi bɔ mli.",
            effects = "Ŋmɔ lɛ fɛɛ baanyɛ afite yɛ gbii 3 kɛyaashi 7 mli kɛji ŋwɛi shishɔŋ sa. Kɛji hela lɛ eyɔɔ yibii lɛ amli lɛ, anyɛɛɛ ahɔ̃ɔ̃ amɛ. Shika laajemɔ wulu, titri yɛ ŋmɔ be lɛ naagbee nugbɔ be mli yɛ Ghana.",
            prevention = "Kaadumɔ tsei lɛ ni amɛbɛŋkɛ amɛhe — ha kɔɔyɔɔ atsɔ amɛteŋ. Kaashwie nu kɛjɛ ŋwɛi. Nyiɛ ŋwɛi shishɔŋ saji asɛɛ yɛ fɛi kɛ nugbɔ be mli ni okɛ tsofa atsu nii dani hela lɛ aaba. Jie tso fɛɛ tso ni hela eyɔɔ mli kɛjɛ jɛi ni oshã amɛ oya. Kaashi nii ni hela eyɔɔ mli yɛ ŋmɔ lɛ mli.",
            organicMitigation = "• Bordeaux mixture (kɔpa sulfate oha mli 1 + tɛ ŋɔɔ): Kɛtsu nii gbii 5 kɛyaashi 7 fɛɛ mli yɛ fɛi kɛ nyɔŋmɔ mli akɛ hebumɔ ni naa wa.\n• Jie tsei kɛ baa fɛɛ ni hela eyɔɔ mli lɛ oya — wo amɛ kotoku mli ni oshã amɛ; kaakɛ amɛ afee compost.\n• Ha nu ajɛ ŋmɔ lɛ mli jogbaŋŋ koni nu akadamɔ shi.\n• Kaadumɔ yɛ hei ni yɔɔ shishi ni kɔɔyɔɔ fɛi bɔleɔ he lɛ.\n• Kɛ kɔpa shɔ (copper octanoate) tsu nii akɛ nɔ ni akpɛlɛ nɔ kɛha adebɔɔ ŋmɔ nitsumɔ.",
            chemicalMitigation = "• Metalaxyl + Mancozeb (Ridomil Gold MZ): Etsuɔ nii fe fɛɛ; kɛtsu nii akɛ hebumɔ gbii 7 kɛyaashi 10 fɛɛ mli yɛ fɛi kɛ nyɔŋmɔ mli.\n• Cymoxanil + Mancozeb (Curzate M): Ebuɔ he ni etsaa hela hu; kɛtsu nii gbii 5 kɛyaashi 7 fɛɛ mli.\n• Dimethomorph (Forum): Eyaa tso lɛ mli; etsuɔ nii kɛha Phytophthora; tsake lɛ kɛ Ridomil teŋ.\n• Fosetyl-aluminum (Aliette): Eyaa tso lɛ mli kɛtsɔ shishifai kɛ baa nɔ; kɛtsu nii akɛ hebumɔ.\n• Tsake tsofai srɔtoi lɛ yɛ shii 2 kɛyaashi 3 fɛɛ sɛɛ koni hela lɛ akadamɔ shi."
        ),

        11 to DiseaseTranslation(
            localName = "Mako Nhwiren Opapaee (fama baa fitemɔ hela)",
            description = "Gbɛi ni akɛtsɛɔ baa gbomɔ oya ni fɔŋ helai loo kooloo bibioi kɛbaa yɛ fama nɔ. Kpakpai wuji diŋ ni amɛsu bɛ ni egbɛleɔ oya ji eokadi, ni ehãa baa gboɔ ni tso lɛ enaa gbɔjɔɔ.",
            symptoms = "Hei wuji shɛɛ diŋ loo nɔ ni tamɔ nɔ ni nu eyɔɔ mli, ni amɛsu bɛ, ni jeɔ shishi kɛjɛ baa lɛ naa loo eyitso nɔ. Baa fã lɛ gboɔ oya ni etsɔɔ shɛɛ tamɔ wolo. Hela ni naa wa hãa baa fɛɛ gboɔ ni egbeɔ shi, ni tso lɛ shwɛɔ yaka.",
            causes = "Babaoo lɛ, Phytophthora capsici yɛ latsa ni naa wa (28 kɛyaashi 32 °C) kɛ bɔ mli. Botrytis cinerea (ejurɔ fɔŋ) hu baanyɛ ekɛba yɛ fɛi kɛ bɔ mli, loo Colletotrichum capsici yɛ he ni bɔ fa waa.",
            effects = "Baa ni gbeɔ shi oya hãa hulu kɛ helai krokomɛi shɛɔ yibii lɛ anɔ. Yibii ni gbeɔ shi dani abe eshɛ kpɔɔ nii lɛ nɔ waa. Baa ni gbeɔ shi shii abɔ hãa tsei lɛ anaa gbɔjɔɔ waa ni ebaanyɛ eha amɛgbo kwraa.",
            prevention = "Fee kpɔi ni kwɔ koni nu ajɛ mli jogbaŋŋ. Kaashwie nu kɛjɛ ŋwɛi. Kpɔɔ tsei ayibɔ nɔ koni kɔɔyɔɔ atsɔ amɛteŋ. Kaatã tsei ahe be ni bɔ yɔɔ amɛhe. Jie nii ni hela eyɔɔ mli lɛ oya ni ofite amɛ.",
            organicMitigation = "• Fɔ Bordeaux mixture akɛ hebumɔ gbii 10 kɛyaashi 14 fɛɛ mli.\n• Fɔ potassium silicate yɛ baa lɛ anɔ koni baa lɛ agbɔi hewalɛ awa.\n• Jie baa ni hela eyɔɔ mli kɛ tsei anii kɛjɛ jɛi oya.\n• Ha nu ajɛ shikpɔŋ mli kɛtsɔ kpɔi ni kwɔ kɛ adebɔɔ nii ni okɛwoɔ mli nɔ.\n• Kɛ Bacillus subtilis tsofa (okadi Serenade) fɔ yɛ baa lɛ anɔ.",
            chemicalMitigation = "• Metalaxyl + Mancozeb: Kɛha hela ni Phytophthora kɛbaa; kɛtsu nii akɛ hebumɔ.\n• Copper hydroxide + Mancozeb: Etsaa helai babaoo; kɛtsu nii kɛji hela lɛ eje kpo.\n• Iprodione (Rovral 500SC): Etsuɔ nii kɛha Botrytis; kɛtsu nii yɛ fɛi kɛ bɔ mli.\n• Azoxystrobin: Eyaa tso lɛ mli; etsaa baa helai babaoo.\n• Kɛ tsofa ni tãa he kɛ nɔ ni yaa tso mli afata he yɛ tank mli koni etsu nii oya."
        ),

        12 to DiseaseTranslation(
            localName = "Mako Nhwiren Kurukuruwa (fama baa bɔlemɔ hela)",
            description = "Hela wu ni hãa baa bɔleɔ waa, efeɔ ŋmɔlɔmɔ, ni tso lɛ daraaa. Kooloo yɛŋi pɛ kɛɔ yaa, ni egbɛleɔ oya yɛ fama ŋmɔji amli titri yɛ gbiŋ be mli be ni kooloo yɛŋi fa. Tsamɔ ko bɛ he; hebumɔ kɛ kooloo lɛ ni aaagbe ji nɔ titri.",
            symptoms = "Baa bɔleɔ kɛyaa ŋwɛi loo shishi waa ni efeɔ ŋmɔlɔmɔ. Baa ni ebɔle lɛ bibioo ni enaa yɔɔ sɛɛ. Tsei ni hela eyɔɔ mli lɛ daraaa, amɛfɔɔɔ jogbaŋŋ, ni amɛwoɔ yibii fioo loo amɛwooo kwraa. Tso lɛ fɛɛ tamɔ nɔ ni efite.",
            causes = "Chilli Leaf Curl Virus (ChiLCV) loo Tomato Leaf Curl Virus (TLCV) ni kooloo yɛŋ (Bemisia tabaci) kɛɔ yaa. Hela wu lɛ nyɛɛɛ egbɛle kɛtsɔ shikpɔŋ, nitsumɔ nii, loo hetamɔ nɔ — ehe hiaa kooloo lɛ.",
            effects = "Tsei ni hela eyɔɔ mli lɛ woɔɔ nii — nii lɛ fɛɛ fiteɔ kɛji hela lɛ eyɔɔ amɛmli be ni amɛda so amɛbibioi. Hela wu lɛ gbɛleɔ oya yɛ ŋmɔ lɛ mli be ni kooloo yɛŋi nyiɛɔ. Nii lɛ fɛɛ baanyɛ afite yɛ hela wulu mli, titri yɛ gbiŋ be mli.",
            prevention = "Fee dumɔhe yɛ tsɔɔmɔ ni tsiɔ kooloo bibioi anaa shishi koni oná tsei ni hela wu bɛ amɛhe. Ha he lɛ akahi kooloo yɛŋi yɛ otsii 3 kɛyaashi 4 klɛŋklɛŋ yɛ dumɔ sɛɛ. Jie tsei ni hela eyɔɔ mli lɛ oya ni ofite amɛ koni hela wu lɛ ahiɛshi akpɔtɔ. Kaadumɔ fama abɛŋkɛ kamatoo, taba, loo amɛwekumɛi.",
            organicMitigation = "• Kɛ nɔ ni kpɛɔ (jwiɛtɛi loo aluminium) tsɔɔ shikpɔŋ nɔ: Ekɛ kooloo yɛŋi ahiɛ tsiɔ kɛtsɔ la ni ekpɛɔ nɔ.\n• Ma sɛɛ tsɔne ni mɔɔ nii (30 yɛ hekta fɛɛ hekta mli): Emɔɔ kooloo yɛŋi ni etsɔɔ amɛyibɔ.\n• Fɔ neem mu (oha mli 3 kɛyaashi 4) kɛ kooloo bibioi ashɔ (oha mli 0.5) otsi fɛɛ otsi: Egbeɔ kooloo yɛŋi bibioi kɛ amɛwui.\n• Dumɔ marigold (Tagetes spp.) yɛ ŋmɔ lɛ masɛi: Ekɛ kooloo yɛŋi shiɔ.\n• Jie tsei fɛɛ ni hela eyɔɔ mli lɛ oya koni hela wu lɛ ahiɛshi akpɔtɔ.",
            chemicalMitigation = "• Imidacloprid (Confidor 200SL): Shwie shikpɔŋ mli loo fɔ yɛ baa lɛ anɔ; etsuɔ nii jogbaŋŋ kɛha kooloo yɛŋi; kɛtsu nii kɛji ona amɛ pɛ.\n• Thiamethoxam (Actara 25WG): Eyaa tso lɛ mli; kɛji ashwie shikpɔŋ mli yɛ dumɔ be mli lɛ, ebuɔ tso lɛ he otsii 4 kɛyaashi 6.\n• Spiromesifen (Oberon): Etsuɔ nii kɛha kooloo yɛŋi bibioi kɛ amɛwui; tsake lɛ kɛ neonicotinoids teŋ.\n• Pyriproxyfen (Admiral): Etsiɔ kooloo yɛŋi adaramɔ naa.\n• Kadimɔ: Tsofa ko tsaaa hela wu kɛji eba momo — ha ohewalɛ fɛɛ ahi kooloo lɛ gbemɔ nɔ."
        ),

        13 to DiseaseTranslation(
            localName = "Mako Nhwiren Mfirimiri (fama baa subaŋ hela)",
            description = "Hela wu ni hãa akpawa ni kpɛɔ, akpawa ni yɔɔ diŋ kɛ sɛɛ afutuɔ yɛ baa lɛ anɔ, ni bei pii lɛ baa lɛ fiteɔ ni tso lɛ daraaa. Kooloo bibioo aphid kɛ hetamɔ kɛɔ yaa, no hewɔ lɛ egbɛleɔ oya yɛ ŋmɔ ni akwɛɔ nɔ jogbaŋŋ mli.",
            symptoms = "Hei ni tsakeɔ yɛ akpawa ni kpɛɔ, sɛɛ kɛ akpawa ni yɔɔ diŋ teŋ (subaŋ) yɛ baa lɛ hiɛ. Baa baanyɛ efee kpitiokpitio, efee ŋmɔlɔmɔ, loo efite. Niji heei daraaa ni amɛfiteɔ. Tsei lɛ woɔ yibii bibioi ni bei pii lɛ efite ni ajara kpɔ.",
            causes = "Tobacco Mosaic Virus (TMV), Cucumber Mosaic Virus (CMV), loo Pepper Mosaic Virus (PepMV). TMV gbɛleɔ kɛtsɔ hetamɔ (dɛŋ, nitsumɔ nii) kɛ dumɔwui ni hela eyɔɔ mli nɔ. CMV lɛ, kooloo bibioo aphid (Myzus persicae, Aphis gossypii) kɛɔ yaa bei pii.",
            effects = "Nii kpɔmɔ ni ji oha mli 30 kɛyaashi 70 yɛ tsei ni hela eyɔɔ mli lɛ anɔ. Yibii daraaa jogbaŋŋ, yibii bibioi ni efite ni ajara kpɔ yɛ jara nɔ. Tsamɔ ko bɛ he. Hela wui ni aphid kɛɔ yaa baanyɛ eyɔɔ ŋmɔ lɛ fɛɛ mli oya kɛji aphid fa.",
            prevention = "Dumɔ fama srɔtoi ni damɔɔ hela nɛɛ naa (aná yɛ IITA kɛ CSIR-SARI dɛŋ yɛ Ghana). Gbe aphid — amɛ ji mɛi ni kɛɔ yaa fe fɛɛ. Fɔ nitsumɔ nii fɛɛ ahe kɛ bleach oha mli 10 loo dãa oha mli 70 dani otsu nii kɛ esɛɛ. Fɔ odɛŋ dani otã tsei ahe. Kaanu taba obɛŋkɛ tsei lɛ (TMV jɛɛhe).",
            organicMitigation = "• Fɔ neem mu (oha mli 2) otsi fɛɛ otsi kɛha aphid — etsuɔ nii kɛha onukpai kɛ bibioi fɛɛ.\n• Jwiɛtɛi ni kpɛɔ ni akɛtsɔɔ shikpɔŋ nɔ: Etsiɔ aphid naa koni amɛkashwie shi.\n• Jie tsei ni hela eyɔɔ mli lɛ oya — wo amɛ kotoku mli, jie amɛ kɛjɛ ŋmɔ lɛ mli, ni ofite amɛ.\n• Fɔ fufɔ ni ajie mu kɛjɛ mli ni akɛ nu efutu (fufɔ 1 : nu 9) yɛ nitsumɔ nii kɛ dɛŋ anɔ — efiteɔ TMV.\n• Dumɔ coriander, dill, loo fennel he koni aphid ahenyɛlɔi (ladybird, lacewing) aba.",
            chemicalMitigation = "• Imidacloprid (Confidor) loo Acetamiprid (Mospilan): Kooloo bibioi atsofa ni yaa tso mli kɛha aphid; kɛtsu nii kɛji ona aphid klɛŋklɛŋ lɛ.\n• Malathion (Malathion 57 EC): Tsofa ni tãa he ni tsuɔ nii kɛha aphid; kɛtsu nii koni ogbe amɛ oya.\n• Tɛ mu (horticultural oil): Ekpɔɔ aphid hewalɛ ni ekɛ CMV gbɛleɔ lɛ nɔ.\n• Pymetrozine (Chess WG): Aphid tsofa ni fiteee kooloo bibioi kpakpai; ekɛ neonicotinoids nyiɛɔ jogbaŋŋ.\n• Tsofa ko tsaaa hela wu — gbɛi fɛɛ atsi hela lɛ naa."
        ),

        14 to DiseaseTranslation(
            localName = "Mako Nhwiren Ponko Ketewa (fama kpakpai bibioi hela)",
            description = "Fɔŋ hela ni feɔ kpakpai bibioi babaoo yɛ fama baa lɛ anɔ, ni ehãa baa gbeɔ shi fiofio. Fɔŋ lɛ daraa yɛ latsa kɛ bɔ mli. Eyɛ mli akɛ enaa waaa tamɔ baa gbomɔ hela de, shi hela ni baa shii abɔ yɛ ŋmɔ be lɛ mli kpɔɔ nii lɛ nɔ waa.",
            symptoms = "Kpakpai bibioi babaoo ni tamɔ kokloi (milimita 2 kɛyaashi 5) ni amɛnaa yɔɔ shɛɛ diŋ ni amɛteŋ yɔɔ ejurɔ-yɛŋ. Anaa nɔ diŋ bibioi (pycnidia — he ni fɔŋ lɛ wui yɔɔ) yɛ ateŋ kɛji akɛ nɔ ni haa nii feɔ wulu kwɛ. Baa ni hela eyɔɔ mli lɛ tsɔɔ sɛɛ ni egbeɔ shi dani ebe eshɛ.",
            causes = "Fɔŋ Septoria capsici. Ehiɔ tsei anii ni hela eyɔɔ mli kɛ shikpɔŋ mli. Nugbɔnɛmɔ hoo kɛ nushwiemɔ ni jɛɔ ŋwɛi kɛɔ ewui yaa. Latsa (20 kɛyaashi 25 °C), bɔ ni fa kɛ nu ni yɔɔ baa lɛ anɔ buaa hela lɛ.",
            effects = "Baa ni gbeɔ shi kɛjɛ shishi kɛyaa ŋwɛi kpɔɔ niyenii ni tso lɛ feɔ kɛ yibii lɛ nɔ. Nii laajemɔ ni ji oha mli 25 kɛyaashi 50 baanyɛ eba yɛ ŋmɔ ni akwɛɛɛ nɔ mli yɛ nugbɔ be mli. Baa ni gbeɔ shi shii abɔ hãa tso lɛ enaa gbɔjɔɔ ni be ni ewoɔ nii lɛ kuɔ.",
            prevention = "Kɛ adebɔɔ nii ni kɛkɛ tsɔɔ tso lɛ shishi koni shikpɔŋ hoo akashɛ baa ni yɔɔ shishi lɛ anɔ. Kaashwie nu kɛjɛ ŋwɛi — kɛ nushwiemɔ ni nyiɛɔ shikome shikome tsu nii. Ha he ni fa fe sɛntimita 60 ahi koni kɔɔyɔɔ atsɔ mli. Jie nii ni hela eyɔɔ mli lɛ kɛjɛ jɛi yɛ nikpamɔ sɛɛ. Tsake nii ni odumɔɔ afii 2 kɛyaashi 3.",
            organicMitigation = "• Kɛ nii tsɔɔ shikpɔŋ nɔ jogbaŋŋ (jwɛi, ŋmãa he wolo) bɔle tsei lɛ ahe koni shikpɔŋ hoo akakɛ hela wui ayafɔ̃.\n• Fɔ kɔpa tsofa (Bordeaux mixture) akɛ hebumɔ gbii 10 kɛyaashi 14 fɛɛ mli.\n• Jie baa ni yɔɔ shishi ni hela eyɔɔ mli lɛ kɛji ona amɛ pɛ koni hela lɛ gbɛlemɔ akpɔtɔ.\n• Fɔ neem mu kɛ bicarbonate fatamɔ koni fɔŋ lɛ akadara.\n• Ha he ahi jogbaŋŋ ni ofolɔ niji ni yɔɔ shishi koni kɔɔyɔɔ atsɔ mli.",
            chemicalMitigation = "• Mancozeb (Dithane M-45): Ebuɔ he; kɛtsu nii gbii 7 kɛyaashi 10 fɛɛ mli yɛ bɔ be mli.\n• Chlorothalonil (Bravo 500): Tsofa ni tãa he ni tsuɔ nii; kɛtsu nii gbii 10 kɛyaashi 14 fɛɛ mli.\n• Tebuconazole (Folicur 250EW): Eyaa tso lɛ mli; ebuɔ he ni etsaa hela hu; kɛtsu nii kɛji hela lɛ eje kpo.\n• Azoxystrobin: Eyaa tso lɛ mli; etsuɔ nii jogbaŋŋ; kɛtsu nii gbii 14 fɛɛ mli.\n• Tsake tsofai awekui yɛ shii 2 kɛyaashi 3 fɛɛ sɛɛ koni hela lɛ akadamɔ shi."
        ),

        // ── KAMATOO ───────────────────────────────────────────────────────────

        15 to DiseaseTranslation(
            localName = "Ntomato Nhwiren Ponko (kamatoo baa kpakpai hela)",
            description = "Kooloo bibioo hela ni fiteɔ nii. Eyɔɔ baa, tsei kɛ yibii ahe yɛ latsa kɛ nyɔŋmɔ mli. Efa yɛ Ghana kamatoo hei yɛ nugbɔ be mli. Kpakpai ni yɔɔ yibii anɔ kpɔɔ ajara kɛ be ni amɛnyɛɔ amɛhiɔ shi lɛ nɔ waa, ni ehãa shika laajeɔ waa.",
            symptoms = "Kpakpai bibioi shɛɛ diŋ, ni tamɔ kokloi loo amɛsu bɛ (milimita 2 kɛyaashi 5), ni sɛɛ ebɔle he yɛ baa lɛ anɔ. Kpakpai lɛ baanyɛ akpɛtɛ afee hei wuji ni egbo. Tsei náa kpakpai diŋ ni tsɔɔ ŋwɛi ni kwɔ. Yibii ni da so náa kpakpai shɛɛ diŋ ni tsɔɔ ŋwɛi tamɔ he kpakpa, ni ehiɔ shi kɛyashi yibii lɛ aaabi.",
            causes = "Kooloo bibioo Xanthomonas perforans (T3/T4), X. vesicatoria, loo amɛwekumɛi. Egbɛleɔ kɛtsɔ nugbɔnɛmɔ hoo, bɔ, nushwiemɔ ni jɛɔ ŋwɛi, nitsumɔ nii ni hela eyɔɔ he, kɛ dumɔwui loo tsei ni hela eyɔɔ mli nɔ. Hela lɛ he hiaa nu yɛ baa lɛ hiɛ kɛyashi miniti 30 kwraa.",
            effects = "Baa ni gbeɔ shi waa hãa hulu shɛɔ yibii lɛ anɔ. Kpakpai ni yɔɔ yibii anɔ kpɔɔ ajara yɛ jara nɔ oha mli 50 kɛyaashi 80. Nii laajemɔ baanyɛ eshɛ oha mli 50 yɛ afii ni hela lɛ fa mli. Akpooɔ kamatoo ni akɛyaa maŋsɛɛ yɛ efitemɔ hewɔ. Kamatoo ni hela eyɔɔ mli lɛ hiii shi etsɛɛɛ yɛ nikpamɔ sɛɛ.",
            prevention = "Kɛ dumɔwui kɛ tsei ni akwɛ akɛ hela bɛ amɛhe pɛ tsu nii. Kaashwie nu kɛjɛ ŋwɛi — kɛ nushwiemɔ ni nyiɛɔ shikome shikome tsu nii. Tsake nii ni odumɔɔ afii 3 ni okɛ nii ni jeee kamatoo weku atsu nii. Kpɔɔ nitsumɔ yɛ ŋmɔ lɛ mli be ni bɔ yɔɔ tsei lɛ ahe. Fɔ nitsumɔ nii ahe yɛ kwɔŋkwɔŋi ateŋ kɛ bleach oha mli 10.",
            organicMitigation = "• Fɔ Bordeaux mixture (kɔpa sulfate oha mli 1 + tɛ ŋɔɔ oha mli 0.5) gbii 7 kɛyaashi 10 fɛɛ mli yɛ bɔ be mli.\n• Fɔ neem mu kɛ castile shɔ fatamɔ akɛ hebumɔ kroko yɛ kɔpa fɔmɔ enyɔ teŋ.\n• Kɛ nii tsɔɔ tsei lɛ ashishi jogbaŋŋ koni shikpɔŋ hoo (hela jɛɛhe) akashɛ nɔ.\n• Jie baa kɛ nii ni hela eyɔɔ mli lɛ kɛjɛ jɛi daa ni ofite amɛ.\n• Compost ni akɛwoɔ shikpɔŋ mli hãa shikpɔŋ lɛ wala hiɔ ni tso lɛ hewalɛ awa.",
            chemicalMitigation = "• Copper hydroxide (Kocide 3000 loo Funguran OH): Kɛtsu nii gbii 7 kɛyaashi 10 fɛɛ mli; enɛ akɛtsuɔ nii fe fɛɛ.\n• Copper oxychloride + Mancozeb (Cuprosan loo Curzate): Fatamɔ ni tsuɔ nii kɛha kooloo bibioi kɛ fɔŋ hela.\n• Streptomycin sulfate (Agri-Mycin): Kɛtsu nii ni otsake lɛ kɛ kɔpa teŋ; kaaha efa fe shii 2 kɛyaashi 3 koni hela lɛ akadamɔ shi.\n• Kasugamycin (Kasumin): Tsofa kroko ni tsuɔ nii kɛha Xanthomonas.\n• Kaakɛ kɔpa tsu nii yɛ latsa kɛ hulu ni naa wa mli koni baa akashã."
        ),

        16 to DiseaseTranslation(
            localName = "Ntomato Nhwiren Ohow Ntem (kamatoo baa shãa oya)",
            description = "Kamatoo fɔŋ helai ni fa fe fɛɛ yɛ je lɛ mli lɛ ekome, ni efa waa yɛ Ghana. Kpakpai subaŋ ni tamɔ nɔ ni akɛ tu shwieɔ nɔ yɛ baa momoi ni yɔɔ shishi lɛ anɔ ji eokadi. Hela ni naa wa baanyɛ eha baa fɛɛ agbe shi, ni ekpɔ nii lɛ nɔ oha mli 50 kɛyaashi 80.",
            symptoms = "Kpakpai diŋ (milimita 5 kɛyaashi 15) ni bɔlei ebɔle he tamɔ nɔ ni akɛ tu shwieɔ nɔ, klɛŋklɛŋ yɛ baa momoi ni yɔɔ shishi lɛ anɔ. Sɛɛ baanyɛ ebɔle kpakpai lɛ ahe. Be ni hela lɛ miikwɔ lɛ, baa tsɔɔ sɛɛ ni egbeɔ shi dani abe eshɛ. Tsei baanyɛ aná kpakpai kakadaŋŋ diŋ ni ekpɔtɔ (kuɛ fitemɔ yɛ tsei bibioi amli).",
            causes = "Fɔŋ Alternaria solani (kɛ A. alternata). Eyɔɔ shikpɔŋ mli kɛ dumɔwu mli fɛɛ. Ehiɔ nii ni eshwɛ lɛ amli. Latsa (24 kɛyaashi 29 °C), bɔ ni fa, kɛ nu kɛ gbiŋ ni tsakeɔ buaa lɛ. Nugbɔnɛmɔ hoo kɛ kɔɔyɔɔ kɛɔ ewui yaa.",
            effects = "Baa gbeɔ shi kɛjɛ shishi kɛyaa ŋwɛi, ni ekpɔɔ niyenii ni tso lɛ feɔ lɛ nɔ waa. Baa ni gbeɔ shi waa hãa hulu shɛɔ yibii lɛ anɔ ni ekpɔɔ ŋɔɔ feemɔ nɔ. Nii laajemɔ ni ji oha mli 50 kɛyaashi 80 baanyɛ eba yɛ ŋmɔ bei ni naa wa amli. Tsei ni enaa egbɔjɔ lɛ náa helai krokomɛi oya.",
            prevention = "Folɔ baa ni yɔɔ shishi ni tãa shikpɔŋ lɛ koni shikpɔŋ hoo akashɛ nɔ. Kɛ nii ni kɛkɛ (jwɛi loo jwɛi ni egbi) tsɔɔ tso lɛ shishi. Ha he ni ji sɛntimita 60 kwraa ahi tsei ateŋ. Kɛ tso loo dade damɔ tsei lɛ ahe koni baa akatã shikpɔŋ. Tsake nii ni odumɔɔ afii 3 ni okɛ nii ni jeee kamatoo weku atsu nii.",
            organicMitigation = "• Kɛ jwɛi loo jwɛi ni egbi (kɛkɛ sɛntimita 8 kɛyaashi 10) tsɔɔ shikpɔŋ nɔ koni shikpɔŋ hoo akashɛ nɔ — enɛ ji hela lɛ gbɛ wulu.\n• Folɔ baa ni yɔɔ shishi ni hela eyɔɔ mli lɛ oya ni ofite amɛ.\n• Fɔ kɔpa sulfate (Bordeaux mixture) gbii 10 fɛɛ mli akɛ hebumɔ.\n• Fɔ neem mu (oha mli 2) kɛha helai bibioi ni baa oya.\n• Fɔ calcium yɛ baa lɛ anɔ (calcium nitrate loo calcium chloride oha mli 0.5) koni baa lɛ agbɔi hewalɛ awa ni hela lɛ gbɛlemɔ akpɔtɔ.",
            chemicalMitigation = "• Chlorothalonil (Bravo 500 loo Daconil): Enɛ akɛtsuɔ nii fe fɛɛ; kɛtsu nii gbii 7 kɛyaashi 10 fɛɛ mli akɛ hebumɔ.\n• Mancozeb (Dithane M-45): Tsofa ni buɔ he jogbaŋŋ; kɛtsu nii ni otsake lɛ kɛ Chlorothalonil teŋ.\n• Azoxystrobin (Amistar): Eyaa tso lɛ mli; kɛtsu nii gbii 14 fɛɛ mli; ehi waa yɛ gbɛjianɔtoo lɛ fɛɛ mli.\n• Difenoconazole (Score 250EC): DMI tsofa; kɛtsu nii kɛji ona hela lɛ klɛŋklɛŋ.\n• Boscalid + Pyraclostrobin (Signum): SDHI kɛ strobilurin fatamɔ kpakpa kɛha hebumɔ yɛ ŋmɔ be lɛ fɛɛ mli."
        ),

        17 to DiseaseTranslation(
            localName = "Ntomato Kobuo (kamatoo gbojemɔ hela)",
            description = "Fɔŋ hela ni yɔɔ shikpɔŋ mli ni fiteɔ nii waa. Etsiɔ tso lɛ nu gbɛi anaa, no hewɔ lɛ nu kɛ niyenii nyɛɛɛ ashɛ tso lɛ fãi lɛ anɔ. Kɛji shikpɔŋ lɛ ená hela lɛ, ehiɔ mli daa. Eji naagba wulu kɛha kamatoo ŋmɔ nitsumɔ yɛ Ghana kooi ahei ni shikpɔŋ latsa sa lɛ amli.",
            symptoms = "Baa tsɔɔ sɛɛ, ni bei pii lɛ ejeɔ shishi kɛjɛ niji loo tso lɛ fã kome nɔ. Baa gbojeɔ yɛ shwane latsa mli. Kɛji ashwie nu nɔ po lɛ gbojemɔ lɛ hiii. Nu gbɛi lɛ su tsakeɔ efeɔ shɛɛ kɛyaashi tsuru, ni anaa kɛji afolɔ tso lɛ yɛ eshishi.",
            causes = "Fɔŋ Fusarium oxysporum f. sp. lycopersici (wekui 1, 2 kɛ 3) ni yɔɔ shikpɔŋ mli. Ehiɔ shikpɔŋ mli daa akɛ chlamydospores (afii 20 kɛ nɔ ni fa). Shikpɔŋ ni latsa yɔɔ mli (25 kɛyaashi 30 °C) kɛ shikpɔŋ ni kaa (pH ni ba 5.5 shishi) buaa lɛ. Ebotea kɛtsɔ shishifai apilamɔ loo adebɔɔ gbɛi anɔ.",
            effects = "Tso lɛ gboɔ yɛ gbii loo otsii fioo sɛɛ kɛji okadii lɛ eje kpo. Nii lɛ fɛɛ baanyɛ afite yɛ ŋmɔji ni hela lɛ eyɔɔ mli waa lɛ amli. Shikpɔŋ lɛ yaa nɔ ehiɛ hela lɛ afii babaoo — nii ni aaadumɔ jɛi wɔsɛɛ lɛ yɔɔ oshara mli. Tsamɔ ko bɛ he. Enɛ ji nɔ ni hãa kamatoo ŋmɔlɔi shiɔ amɛŋmɔji.",
            prevention = "Dumɔ dumɔwui ni damɔɔ Fusarium naa pɛ (taomɔ F, FF loo FFF yɛ dumɔwu kotoku lɛ nɔ — etsɔɔ damɔmɔ kɛha wekui 1, 2 kɛ 3). Ha shikpɔŋ lɛ pH ahi 6.5 kɛyaashi 7.0 kɛtsɔ tɛ ŋɔɔ nɔ. Ha nu ajɛ shikpɔŋ mli jogbaŋŋ. Ná tsei bibioi kɛjɛ dumɔhei ni akwɛ pɛ. Kaadumɔ kamatoo ekoŋŋ yɛ shikpɔŋ ni hela eyɔɔ mli lɛ mli kɛyashi afii 5 kɛyaashi 7.",
            organicMitigation = "• Shikpɔŋ shãa kɛ hulu: Shwie nu shikpɔŋ lɛ nɔ jogbaŋŋ, ni okɛ plastik ni hiɛ tse ni ji micron 50 tsɔɔ nɔ otsii 4 kɛyaashi 6 yɛ latsa be mli — ekpɔɔ Fusarium nɔ oha mli 90 yɛ sɛntimita 15 klɛŋklɛŋ lɛ mli.\n• Trichoderma harzianum (okadi Trichomax, Biomax-T): Kɛfata dumɔ gbolɔ lɛ he loo shwie shikpɔŋ mli; ekɛ Fusarium yeɔ ni efiteɔ lɛ.\n• Fɔŋ kpakpa (Glomus intraradices): Kɛwo shishifai ahe yɛ dumɔ be mli; ehãa niyenii nine kɛ shishifai ahewalɛ yaa nɔ.\n• Neem yibii ni akwɛ: Kɛ gram 200 fata dumɔ gbolɔ lɛ he kɛha tso fɛɛ tso.\n• Compost ni akɛwoɔ mli: Ehãa shikpɔŋ lɛ wala hiɔ, ni no tsiɔ Fusarium naa.",
            chemicalMitigation = "• Carbendazim (Bavistin 50WP): Shwie shikpɔŋ mli yɛ dumɔ be mli akɛ hebumɔ pɛ.\n• Metalaxyl + Thiram: Dumɔwu tsofa koni ebu tsei bibioi ashishifai ahe yɛ shwiemɔ be mli.\n• Fludioxonil (Maxim): Dumɔwu tsofa ni tsuɔ nii jogbaŋŋ kɛha Fusarium kuɛ kɛ shishifai fitemɔ.\n• Metam sodium (shikpɔŋ tsofa): Akɛtsuɔ nii yɛ shihilɛi ni naa wa amli dani adumɔ — ehe hiaa mɔ ni le nitsumɔ lɛ.\n• Nɔ ni he hiaa: Tsofa ko ni yaa tso mli tsaaa Fusarium gbojemɔ hela kɛji ebote nu gbɛi lɛ amli momo."
        ),

        18 to DiseaseTranslation(
            localName = "Ntomato Pa (kamatoo ni yɔɔ hewalɛ mli)",
            description = "Kamatoo tso nɛɛ yɔɔ hewalɛ mli jogbaŋŋ, edaraa jogbaŋŋ ni hewalɛ yɔɔ enɔ akɛ eaawo yibii babaoo. Kamatoo ni yɔɔ hewalɛ mli ni akwɛɔ nɔ jogbaŋŋ woɔ yibii babaoo ni sa, ni ebuaa ŋmɔlɔi asɛɛnamɔ kɛ niyenii yɛ Ghana.",
            symptoms = "Baa akpawa ni yɔɔ diŋ pɛpɛɛpɛ, kpakpai, kwɔŋkwɔŋi, sɛɛtsɔɔmɔ loo gbojemɔ bɛ he. Tsei ni ewaa ni tereɔ tso lɛ tsii. Fɔfɔi sɛɛ ni tamɔ ŋulami. Yibii ni da so ni yɔɔ tromtrom ni amɛsu yɔɔ pɛpɛɛpɛ, ni etsɔɔ tsuru jogbaŋŋ kɛji ebi.",
            causes = "Shikpɔŋ pH ni sa (6.0 kɛyaashi 6.8), nushwiemɔ daa ni sa (milimita 25 kɛyaashi 40 yɛ otsi mli), NPK ŋmɔ mli tsofa ni sa kɛ niyenii bibioi, he ni sa yɛ tsei ateŋ, kɛ kooloo bibioi kɛ helai ni akwɛɔ amɛnɔ daa.",
            effects = "Yibii babaoo, yibii ni edara, ŋɔɔmɔ kpakpa, su kpakpa kɛ be kakadaŋŋ ni enyɛɔ ehiɔ shi. Tsei ni ewaa damɔɔ naagbai ni baa daa anaa. Nii ni woɔ daa hãa ŋmɔlɔ náa sɛɛnamɔ ni niyenii yɔɔ shia.",
            prevention = "Ya nɔ nɔ ni ofeɔ lɛ nɔ. Kwɛ tsei lɛ anɔ shii enyɔ yɛ otsi mli koni ona hela loo kooloo bibioi okadi klɛŋklɛŋ. Kwɛ tsei loo dadei ni okɛdamɔɔ lɛ anɔ be ni tso lɛ miidara. Folɔ niji ni woɔɔ yibii koni hewalɛ lɛ aya yibii lɛ anɔ. Ŋmalɛ dumɔ, nii ni okɛtsuɔ nii, kɛ nɔ ni ona lɛ.",
            organicMitigation = "• Kɛ adebɔɔ nii ni efite jogbaŋŋ (kilo 3 kɛyaashi 5 kɛha tso fɛɛ tso) wo mli yɛ dumɔ be mli.\n• Kɛ jwɛi loo jwɛi ni egbi (kɛkɛ sɛntimita 10) tsɔɔ shikpɔŋ nɔ koni bɔ ahi mli ni jwɛi akashwie.\n• Kɛ bamboo tsei loo dade tsɔne damɔ tsei lɛ ahe koni tso lɛ akakuɔ ni kɔɔyɔɔ atsɔ mli.\n• Dumɔ basil (ekɛ thrips kɛ aphid shiɔ) kɛ marigold (ekɛ nematode kɛ kooloo yɛŋi shiɔ) he.\n• Fɔ tsei anu ni ekaa loo compost nu yɛ baa lɛ anɔ koni tso lɛ hewalɛ awa.",
            chemicalMitigation = "• Kɛ NPK 15-15-15 tsu nii yɛ dumɔ be mli, ni no sɛɛ lɛ otsake kɛya tsofa ni nitrogen fioo yɔɔ mli (okadi 8-24-24) yɛ yibii be mli.\n• Fɔ calcium nitrate (oha mli 0.5) yɛ baa lɛ anɔ yɛ fɔfɔi be mli koni yibii lɛ shishi akafite.\n• Fɔ kɔpa (Bordeaux mixture) akɛ hebumɔ yɛ nugbɔ be shishijee.\n• Kooloo bibioi atsofa gbɛjianɔtoo ni buɔ he kɛha kooloo yɛŋi kɛ aphid (kɛ Imidacloprid kã dumɔwu lɛ he yɛ dumɔhe be mli).\n• Kɛ potassium sulfate tsu nii be ni yibii lɛ miidara koni esu kɛ ehewalɛ aya nɔ."
        ),

        19 to DiseaseTranslation(
            localName = "Ntomato Nhwiren Kwanee (kamatoo baa gbomɔ hela)",
            description = "Kamatoo hela ni asheɔ agbeyei fe fɛɛ yɛ je lɛ mli — hela lɛ nɔŋŋ kɛ Ireland hɔmɔ wulu lɛ ba yɛ afii 1840 amli. Ebaanyɛ efite kamatoo ŋmɔji fɛɛ yɛ gbii 7 kɛyaashi 10 mli yɛ fɛi kɛ nyɔŋmɔ mli. Efiteɔ kamatoo ŋmɔ nitsumɔ yɛ Ghana nugbɔ bei amli. Kɛji ona lɛ, esa akɛ ofee oya.",
            symptoms = "Kpakpai wuji (sɛntimita 2 kɛyaashi 3) ni yɔɔ diŋ, ejurɔ-shɛɛ, ni tamɔ nɔ ni akɛ mu efɔ nɔ, yɛ baa kɛ tsei ahe. Kɛji bɔ fa lɛ, fɔŋ yɛŋ ni yɔɔ mlɛo jeɔ kpo yɛ baa lɛ eshishi. Kpakpai shɛɛ diŋ ni ewaa yɛ yibii anɔ. Tsei ni hela eyɔɔ mli gbeɔ shi. Ŋmɔji fɛɛ baanyɛ atamɔ nɔ ni la eshɛ nɔ yɛ gbii fioo mli.",
            causes = "Phytophthora infestans. Kɔɔyɔɔ kɛ ewui yaa kilomita 50 kɛ nɔ ni fa. Nyɔŋ fɛi (10 kɛyaashi 20 °C) kɛ bɔ ni fa sa hela lɛ fe fɛɛ. Tso kome ni hela eyɔɔ mli loo abodwese ŋmɔ ni bɛŋkɛ ni hela eyɔɔ mli baanyɛ eje hela lɛ shishi.",
            effects = "Nii lɛ fɛɛ fiteɔ yɛ gbii 7 kɛyaashi 10 mli kɛji shihilɛ lɛ sa hela lɛ. Kɛji hela lɛ eyɔɔ yibii lɛ amli lɛ, anyɛɛɛ ahɔ̃ɔ̃ nii lɛ fɛɛ. Shika laajemɔ wulu — hela nɛɛ ni baaba shikome baanyɛ efite ŋmɔlɔi maŋ fɛɛ. Eji tsei ahelai ni fiteɔ nii fe fɛɛ yɛ je lɛ mli lɛ ekome.",
            prevention = "Dumɔ dumɔwui ni damɔɔ hela lɛ naa (okadi Ferline, Legend, Defiant) kɛji amɛyɔɔ. Nyiɛ ŋwɛi shishɔŋ saji asɛɛ — nyɔŋ fɛi kɛ bɔ ni fa tsɔɔ oshara wulu. Kɛ tsofa tsu nii dani okadii klɛŋklɛŋ aaje kpo yɛ oshara be mli. Ha ŋmɔ lɛ ahi gbiŋ — kaashwie nu kɛjɛ ŋwɛi. Kwɛ ŋmɔ lɛ nɔ gbi fɛɛ gbi yɛ fɛi kɛ nugbɔ bei amli.",
            organicMitigation = "• Bordeaux mixture (kɔpa sulfate oha mli 3 kɛyaashi 4 + tɛ ŋɔɔ oha mli 3): Fɔ gbii 5 kɛyaashi 7 fɛɛ mli yɛ fɛi kɛ nyɔŋmɔ mli — enɛ ji adebɔɔ hebumɔ titri.\n• Jie tsei fãi FƐƐ ni hela eyɔɔ mli lɛ oya ni ofite — wo amɛ kotoku mli, jie amɛ kɛjɛ ŋmɔ lɛ mli, kaakɛ amɛ afee compost.\n• Ha nu ajɛ ŋmɔ lɛ mli jogbaŋŋ ni kaadumɔ yɛ hei ni yɔɔ shishi.\n• Copper octanoate (Cueva): Kɔpa tsofa ni akpɛlɛ nɔ kɛha adebɔɔ ŋmɔ nitsumɔ; kɛtsu nii gbii 5 fɛɛ mli yɛ oshara bei amli.\n• Kaashwie nu kɛjɛ ŋwɛi yɛ fɛi bei amli — kɛ nushwiemɔ ni nyiɛɔ shikome shikome pɛ tsu nii.",
            chemicalMitigation = "• Metalaxyl + Mancozeb (Ridomil Gold MZ 68WG): Tsofa klɛŋklɛŋ; kɛtsu nii gbii 7 fɛɛ mli akɛ hebumɔ yɛ fɛi kɛ nyɔŋmɔ mli — kaamɛ okadii lɛ.\n• Cymoxanil + Famoxadone (Equation Pro): Fatamɔ ni yaa tso mli ni ebuɔ he hu; kɛtsu nii gbii 5 kɛyaashi 7 fɛɛ mli.\n• Dimethomorph (Forum): Eyaa tso lɛ mli; etsuɔ nii yɛ hela ni baa oya sɛɛ; tsake lɛ kɛ Ridomil teŋ.\n• Fluopicolide + Propamocarb (Infinito): Eyaa tso lɛ mli jogbaŋŋ; kɛtsu nii gbii 7 kɛyaashi 10 fɛɛ mli.\n• Tsake tsofai akui fɛɛ yɛ shii 2 fɛɛ sɛɛ, ejaakɛ Phytophthora damɔɔ tsofa naa oya waa."
        ),

        20 to DiseaseTranslation(
            localName = "Ntomato Nhwiren Kurukuruwa (kamatoo baa bɔlemɔ hela)",
            description = "Atsɛɔ lɛ hu akɛ kamatoo baa sɛɛ bɔlemɔ (TYLCV). Hela wu nɛɛ ni kooloo yɛŋi kɛɔ yaa lɛ ji kamatoo helai ni fiteɔ nii fe fɛɛ yɛ je lɛ mli lɛ ekome. Kooloo yɛŋ Bemisia tabaci pɛ kɛɔ yaa. Efiteɔ nii waa yɛ Ghana gbiŋ be mli be ni kooloo yɛŋi fa waa.",
            symptoms = "Baa bɔleɔ kɛyaa ŋwɛi kɛ mli waa, ni amɛnaa tsɔɔ sɛɛ. Baa ni hela eyɔɔ mli lɛ bibioo, ekɛkɛ ni ewaa. Tso lɛ fãi ateŋ ni kuɔ hãa tso lɛ tamɔ kooshi bibioo. Edaraaa kwraa — tso lɛ tsɔɔɔ sɛntimita 30. Ewoɔɔ yibii kwraa; kɛji ewo eko lɛ, ebibioi ni amɛsu ehiii.",
            causes = "Tomato Yellow Leaf Curl Virus (TYLCV), Begomovirus ni Bemisia tabaci pɛ kɛɔ yaa. Kooloo yɛŋ kome ni hela wu yɔɔ ehe baanyɛ eha tso lɛ ená hela lɛ yɛ miniti fioo mli. Gbɛ kroko ko bɛ he ni etsɔɔ nɔ — jeee shikpɔŋ loo nitsumɔ nii nɔ.",
            effects = "Nii lɛ fɛɛ fiteɔ kɛji tsei lɛ ená hela lɛ yɛ otsii 3 kɛyaashi 4 klɛŋklɛŋ yɛ dumɔ sɛɛ. Mɛi ni ná hela lɛ sɛɛ mli lɛ baanyɛ awo oha mli 20 kɛyaashi 30 pɛ. Hela wu lɛ gbɛleɔ oya — kooloo yɛŋi kuu kome baanyɛ eyɔɔ ŋmɔ lɛ fɛɛ mli yɛ otsii 2 mli. Shika laajemɔ wulu, titri yɛ gbiŋ be kamatoo ŋmɔ nitsumɔ mli.",
            prevention = "Fee dumɔhe yɛ tsɔɔmɔ ni mli bibioo (mesh 50) shishi koni oná tsei ni kooloo yɛŋi bɛ amɛhe. Fee ŋmɔ hee lɛ shɔŋŋ kɛjɛ kamatoo ŋmɔji ni hela eyɔɔ mli lɛ ahe. Jie kamatoo ni ekwɛ ekɛ ehe fɛɛ ni ofite, ejaakɛ jɛi hela wu lɛ hiɔ. Kwɛ kooloo yɛŋi ayibɔ nɔ kɛ sɛɛ tsɔne ni mɔɔ nii kɛjɛ dumɔ be mli.",
            organicMitigation = "• Tsɔɔmɔ ni mli bibioo (mesh 50) ni akɛtsɔɔ dumɔwu kpɔi anɔ: Etsiɔ kooloo yɛŋi anaa koni amɛkashɛ tsei bibioi ahe yɛ daramɔ be ni he hiaa lɛ mli.\n• Jwiɛtɛi loo aluminium ni kpɛɔ ni akɛtsɔɔ shikpɔŋ nɔ: Ekɛ kooloo yɛŋi shiɔ; etsuɔ nii jogbaŋŋ yɛ ŋmɔ be shishijee.\n• Sɛɛ tsɔne ni mɔɔ nii (20 kɛyaashi 30 yɛ hekta fɛɛ hekta mli): Emɔɔ kooloo yɛŋi onukpai ni etsɔɔ amɛyibɔ.\n• Fɔ neem mu (oha mli 3 kɛyaashi 4) kɛ kooloo bibioi ashɔ otsi fɛɛ otsi: Etsaa kooloo yɛŋi bibioi kɛ amɛwui.\n• Jie tsei fɛɛ ni hela eyɔɔ mli lɛ oya ni ofite — amɛji hela wu lɛ jɛɛhe daa kɛha ŋmɔ lɛ fɛɛ.",
            chemicalMitigation = "• Imidacloprid (Confidor 200SL) ni ashwieɔ shikpɔŋ mli yɛ dumɔ be mli: Ebuɔ tso lɛ he otsii 4 kɛyaashi 6 — enɛ ji hebumɔ gbɛ kpakpa fe fɛɛ yɛ shishijee.\n• Thiamethoxam (Actara 25WG) akɛ dumɔwu tsofa loo ashwie shikpɔŋ mli: Etsaa kooloo yɛŋi jogbaŋŋ.\n• Spiromesifen (Oberon): Eyaa kooloo yɛŋi awui kɛ amɛbibioi anɔ; tsake lɛ kɛ neonicotinoids teŋ koni amɛkadamɔ shi.\n• Buprofezin (Applaud): Etsiɔ kooloo yɛŋi ahe wolo tsakemɔ naa; kɛtsu nii yɛ tsakemɔ mli.\n• Nɔ ni he hiaa: Hela wu tsofa ko bɛ he — esa akɛ mɔdɛŋbɔɔ fɛɛ ayaa kooloo lɛ nɔ dani ekɛ hela lɛ aaba."
        ),

        21 to DiseaseTranslation(
            localName = "Ntomato Nhwiren Mfirimiri (kamatoo baa subaŋ hela)",
            description = "Hela wu ni waa ni gbɛleɔ kɛtsɔ hetamɔ nɔ, ni ehãa subaŋ kɛ kpɔkpɔi baa yɛ kamatoo baa lɛ anɔ. Tobacco Mosaic Virus (TMV) ji tsei ahelai ni akaseɔ ahe nii fe fɛɛ lɛ ekome — ewaa waa ni ebaanyɛ ehi taba ni egbi mli afii babaoo. Nitsumɔ nii kɛ dɛŋ ni hela yɔɔ he ji gbɛi titri ni etsɔɔ nɔ gbɛleɔ yɛ ŋmɔ ni akwɛɔ nɔ mli.",
            symptoms = "Hei ni tsakeɔ yɛ akpawa ni kpɛɔ kɛ akpawa ni yɔɔ diŋ teŋ yɛ baa lɛ anɔ (subaŋ). Baa baanyɛ efite, efee kpitiokpitio, loo efee tamɔ kpãa. Baa lɛ hiɛ baanyɛ efee kpɔkpɔkpɔ. Kwɔŋkwɔŋi shɛɛ loo diŋ ni ekpɔtɔ yɛ tsei ahe. Yibii baanyɛ etsɔɔ subaŋ sɛɛ loo shɛɛ yɛ mli.",
            causes = "Tobacco Mosaic Virus (TMV) loo Tomato Mosaic Virus (ToMV). Egbɛleɔ kɛtsɔ hetamɔ nɔ titri: dɛŋ, nitsumɔ nii, atadei, kɛ kooloo bibioi ni nuɔ nii. TMV waa waa — ehiɔ taba ni egbi mli, shikpɔŋ mli, kɛ nii ahiɛ nyɔji kɛyaashi afii. Dumɔwui ni hela eyɔɔ mli baanyɛ akɛ ehã.",
            effects = "Nii kpɔmɔ ni ji oha mli 10 kɛyaashi 35 kɛtsɔ yibii ni daraaa jogbaŋŋ kɛ yibii bibioi ni esui ehiii nɔ. Anyɛɛɛ ahɔ̃ɔ̃ yibii ni subaŋ yɔɔ anɔ. TMV hiɔ shi etsɛɔ waa — ŋmɔ baanyɛ ehiɛ hela lɛ afii babaoo. Tso ni hela eyɔɔ mli ko tsaaa. Egbɛleɔ oya he ni adumɔ tsei babaoo abɔle.",
            prevention = "Dumɔ dumɔwui ni damɔɔ hela wu lɛ naa pɛ (Tm-2 hewalɛ — eyɔɔ kamatoo srɔtoi heei babaoo mli). Fɔ nitsumɔ nii fɛɛ ahe kɛ bleach oha mli 10 loo dãa oha mli 70 dani okɛtsu nii kɛ yɛ tsei ateŋ. Fɔ odɛŋ jogbaŋŋ kɛ shɔ dani otã tsei ahe. Kaanu taba ni kaatã taba nii ahe obɛŋkɛ kamatoo kɔkɔɔkɔ (TMV jɛɛhe). Jie tsei ni hela eyɔɔ mli lɛ oya.",
            organicMitigation = "• Dumɔ dumɔwui ni damɔɔ TMV/ToMV naa (Tm-2 loo Tm-2² hewalɛ) — enɛ pɛ ji hebumɔ kpakpa fe fɛɛ.\n• Fɔ fufɔ ni ajie mu kɛjɛ mli (1:10 kɛ nu): Efiteɔ hela wu lɛ nii yɛ tsei kɛ nitsumɔ nii ahiɛ; fɔ yɛ nitsumɔ nii kɛ dɛŋ anɔ dani otsu nii.\n• Jie tsei ni hela eyɔɔ mli lɛ oya ni ofite — kaakɛ amɛ afee compost; wo amɛ kotoku mli ni oshã amɛ.\n• Kɛ nu ni edɔ (50 °C miniti 30) fee dumɔwu lɛ koni hela wu ni yɔɔ dumɔwu mli lɛ ajie dani odumɔ.\n• Kaakɛ nitrogen babaoo tsu nii, ejaakɛ ehãa tso lɛ feɔ mlɛo ni enaa hela lɛ oya.",
            chemicalMitigation = "• Tsofa ko tsaaa hela wu yɛ tsei amli.\n• Imidacloprid loo Acetamiprid: Amɛtsaa kooloo bibioi ni nuɔ nii (aphid, thrips) ni amɛbaanyɛ akɛ hela lɛ awo tso lɛ mli be ni amɛyeɔ nii.\n• Tsei ahewalɛ tsofai (Acibenzolar-S-methyl / Actigard): Ehãa tso lɛ diɛŋtsɛ ehewalɛ teɔ shi; ebaanyɛ ekpɔ okadii lɛ naa wamɔ nɔ bei komɛi.\n• Tɛ mu (horticultural oil): Kɛji afɔ yɛ baa lɛ anɔ lɛ, ebaanyɛ ekpɔ hetamɔ gbɛlemɔ nɔ.\n• Esa akɛ nitsumɔ lɛ fɛɛ adamɔ hetsemɔ, dumɔwui ni damɔɔ hela naa, kɛ tsei ni hela eyɔɔ mli ni ajieɔ nɔ."
        ),

        22 to DiseaseTranslation(
            localName = "Ntomato Nhwiren Ponko Ketewa (kamatoo kpakpai bibioi hela)",
            description = "Kamatoo fɔŋ helai ni fa fe fɛɛ lɛ ekome, ni efeɔ kpakpai babaoo ni ehãa baa gbeɔ shi fiofio kɛjɛ shishi kɛyaa ŋwɛi. Egbɛle waa yɛ Ghana nugbɔ be mli. Eyɛ mli akɛ egbeee tsei kɛkɛ de, shi baa ni gbeɔ shi shii abɔ kpɔɔ nii kɛ yibii asui nɔ waa.",
            symptoms = "Kpakpai bibioi babaoo ni tamɔ kokloi (milimita 2 kɛyaashi 5) ni amɛnaa yɔɔ shɛɛ diŋ faŋŋ ni amɛteŋ yɔɔ yɛŋ kɛyaashi ejurɔ yɛ baa lɛ anɔ. Anaa nɔ diŋ bibioi (pycnidia — he ni fɔŋ wui yɔɔ) yɛ kpakpai lɛ ateŋ kɛji akɛ nɔ ni haa nii feɔ wulu kwɛ. Baa ni hela eyɔɔ mli lɛ tsɔɔ sɛɛ ni egbeɔ shi. Hela lɛ kwɔɔ kɛjɛ baa ni yɔɔ shishi lɛ anɔ kɛyaa ŋwɛi.",
            causes = "Fɔŋ Septoria lycopersici. Eyɔɔ shikpɔŋ mli ni ehiɔ nii ni hela eyɔɔ mli lɛ amli. Egbɛleɔ kɛtsɔ nugbɔnɛmɔ hoo, nushwiemɔ ni jɛɔ ŋwɛi, kɛ tsei ni hela eyɔɔ mli ni atãa amɛhe nɔ. Latsa (20 kɛyaashi 25 °C) kɛ bɔ ni hiɔ baa lɛ nɔ etsɛɔ buaa lɛ.",
            effects = "Baa ni gbeɔ shi kɛjɛ shishi kɛyaa ŋwɛi kpɔɔ niyenii ni tso lɛ feɔ lɛ nɔ ni ehãa hulu shɛɔ yibii lɛ anɔ. Nii laajemɔ ni ji oha mli 30 kɛyaashi 60 fa yɛ ŋmɔji ni akwɛɛɛ nɔ lɛ amli yɛ bɔ bei amli. Baa ni gbeɔ shi shii abɔ hãa tso lɛ enaa gbɔjɔɔ ni ekpɔɔ ŋmɔ be lɛ fɛɛ nii lɛ nɔ. Yibii ni eshwɛ lɛ asui hu fiteɔ yɛ hulu hewɔ.",
            prevention = "Kɛ adebɔɔ nii ni kɛkɛ (sɛntimita 5 kɛyaashi 8) tsɔɔ tso lɛ shishi koni nugbɔnɛmɔ akakɛ shikpɔŋ (hela wui jɛɛhe wulu) ashwie baa ni yɔɔ shishi lɛ anɔ. Folɔ baa ni yɔɔ shishi kɛji tsei lɛ edara. Kɛ nushwiemɔ ni nyiɛɔ shikome shikome tsu nii — kaaha nu ashɛ baa lɛ anɔ. Ha he ni fa fe sɛntimita 60 ahi koni kɔɔyɔɔ atsɔ mli. Tsake nii ni odumɔɔ afii 3 ni okɛ nii ni jeee kamatoo weku atsu nii.",
            organicMitigation = "• Kɛ nii tsɔɔ shikpɔŋ nɔ jogbaŋŋ bɔle tsei lɛ ahe (jwɛi, ŋmãa he wolo, jwɛi ni egbi): Etsiɔ shikpɔŋ hoo naa, ni no ji hela lɛ jɛɛhe wulu.\n• Folɔ baa ni yɔɔ shishi ni hela eyɔɔ mli lɛ oya ni ojie amɛ kɛjɛ ŋmɔ lɛ mli.\n• Fɔ kɔpa sulfate (Bordeaux mixture) gbii 10 kɛyaashi 14 fɛɛ mli akɛ hebumɔ yɛ bɔ bei amli.\n• Fɔ bicarbonate kɛ neem mu fatamɔ (neem mu kpaŋmɔ wulu 1 + baking soda kpaŋmɔ bibioo 1 yɛ nu lita fɛɛ lita mli): Etsakeɔ baa lɛ hiɛ shishɔŋ ni etsiɔ fɔŋ wui adaramɔ naa.\n• Fɔ compost nu yɛ baa lɛ anɔ: Nii bibioi kpakpai kɛ Septoria yeɔ ni amɛtsiɔ enaa.",
            chemicalMitigation = "• Chlorothalonil (Bravo 500 loo Daconil 2787): Enɛ akɛtsuɔ nii fe fɛɛ; kɛtsu nii gbii 7 kɛyaashi 10 fɛɛ mli akɛ hebumɔ.\n• Mancozeb (Dithane M-45): Tsofa ni buɔ he jogbaŋŋ; kɛtsu nii ni otsake lɛ kɛ Chlorothalonil teŋ.\n• Azoxystrobin (Amistar loo Quadris): Eyaa tso lɛ mli; etsuɔ nii jogbaŋŋ; kɛtsu nii gbii 14 fɛɛ mli.\n• Propiconazole (Tilt 250EC): DMI tsofa ni yaa tso mli; kɛtsu nii yɛ hela lɛ shishijee koni etsa lɛ.\n• Trifloxystrobin + Tebuconazole (Nativo 75WG): Fatamɔ kpakpa; etsaa Septoria jogbaŋŋ yɛ ŋmɔ be lɛ fɛɛ mli."
        )
    )
}
